INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5576', 'spa', 'Senaquerib; rey de Asiria (705–681 a.C.) que invadió Judá durante el reinado de Ezequías.', 'El nombre acadio Sin-ahhe-eriba significa «Sin (el dios lunar) ha reemplazado a los hermanos», siguiendo las convenciones onomásticas de la realeza asiria. Senaquerib sucedió a su padre Sargón II y es recordado en la historia bíblica principalmente por su campaña contra Judá en el 701 a.C. (2 R 18:13–19:37; Is 36–37; 2 Cr 32). Su asedio a Jerusalén terminó dramáticamente cuando el ángel del SEÑOR hirió a 185.000 soldados asirios en una sola noche. Posteriormente, Senaquerib fue asesinado por sus propios hijos mientras adoraba en el templo de su dios Nisroc (2 R 19:36–37). Las diversas lenguas transliteran el nombre con variaciones menores: en español «Senaquerib», en francés «Sanchérib».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5577', 'spa', 'ramas/racimos de dátiles — tallos frutales o racimos de la palmera datilera', 'Este término designa partes de la palmera datilera, probablemente los tallos frutales o los racimos donde crecen los dátiles. Aparece en el poema de amor culminante del Cantar de los Cantares, donde el amado declara su intención de subir a la palmera y agarrar sus racimos. El análisis filológico lo identifica como un préstamo arameo relacionado con términos siríacos para racimos de dátiles. El contexto romántico emplea la imagen de la palmera para representar la estatura y el atractivo de la amada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5578', 'spa', 'Sansaná — ciudad en el sur de Judá, posiblemente significa ''rama de palmera''', 'Sansaná era una ciudad en el territorio meridional asignado a Judá durante la conquista. Parece ser idéntica a Hazar-susa, mencionada en Josué 19:5, y a Hazar-susim en 1 Crónicas 4:31, mostrando la variación típica de topónimos bíblicos. Se ubicaba cerca de Gaza, aunque su identificación precisa sigue siendo incierta. Se han propuesto varios sitios al noreste de Gaza, pero falta confirmación arqueológica. El nombre podría estar relacionado con ramas de palmera o con terminología ecuestre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5579', 'spa', 'aleta (de pez); marca distintiva de las criaturas acuáticas ritualmente puras', 'Término técnico de las leyes dietéticas levíticas que designa la aleta de un pez o criatura acuática. Aparece exclusivamente en los textos legales paralelos de Levítico 11:9-12 y Deuteronomio 14:9-10, siempre emparejado con las escamas (קַשְׂקֶשֶׂת) como los dos indicadores que determinan si una criatura acuática es pura y apta para el consumo. Las criaturas que poseen aletas y escamas son puras; las que carecen de alguna de ambas son «abominación». La notable uniformidad en las traducciones refleja la precisión de esta categoría biológico-legal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5580', 'spa', 'polilla/gusano — insecto que consume tejidos', 'Este término designa la polilla de la ropa o un insecto similar que devora tejidos. Isaías lo emplea en una poderosa imagen del juicio divino, declarando que la polilla consumirá a los malvados como a una vestidura. La comparación funciona porque las polillas destruyen silenciosa y gradualmente los textiles costosos, tal como el juicio de Dios actúa persistentemente contra los impíos. Términos relacionados aparecen en arameo, siríaco, árabe y otras lenguas semíticas, todos referidos a insectos destructores que devoran tela o madera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5582', 'spa', 'Sostener, sustentar o apoyar; por extensión, reconfortarse con alimento, tomar una comida', 'Verbo hebreo que expresa la idea de apuntalar, sustentar o prestar fuerza a alguien. En la mayoría de sus apariciones describe a Dios sosteniendo al justo (Sal 18:35) o a la lealtad sustentando a un rey (Pr 20:28). La imagen física es la de mantener a alguien en pie. En un uso distintivo (1 Re 13:7), el término pasa a significar reconfortarse con alimento, expresión concreta de sustentar el cuerpo que pervive en el arameo tardío y en el hebreo rabínico, donde se convirtió en el término estándar para tomar una comida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5583', 'spa', 'apoyar/ayudar — prestar asistencia activa', 'Este verbo arameo aparece en el relato de Esdras sobre la reconstrucción del templo, describiendo cómo los profetas Hageo y Zacarías apoyaban y alentaban activamente la obra. La forma intensiva Pael enfatiza una asistencia sostenida y enérgica. La raíz aparece en el arameo targúmico y en siríaco con significado similar. El contexto muestra que el ministerio profético no se limitaba a palabras, sino que incluía apoyo práctico y activo para el proyecto de reconstrucción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5584', 'spa', 'tempestuoso/impetuoso — viento violento y arrollador', 'Este verbo poco frecuente describe un viento violento e impetuoso, específicamente el movimiento feroz de una tormenta. El salmista lo emplea en paralelo con ''tempestad'', creando un par léxico que evoca fuerzas naturales abrumadoras. La raíz sugiere movimiento rápido y energía arrolladora, presente en cognados árabes que significan ''ir rápidamente'' o ''correr con energía''. Su única aparición dificulta una definición precisa, pero el contexto indica claramente fenómenos meteorológicos destructivos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5585', 'spa', 'Hendidura o grieta en la roca; rama o ramaje de un árbol', 'El sustantivo סָעִיף evoca dos imágenes vívidas del mundo natural. En su sentido primario designa una hendidura o fisura en un peñasco rocoso, un lugar de ocultamiento, como cuando Sansón habitó en la hendidura de la peña de Etam (Jue 15:8, 11) o cuando Isaías describe a la gente escondiéndose en las grietas de las rocas en el día del SEÑOR (Isa 2:21). En su sentido secundario se refiere a las ramas o el ramaje de un árbol, empleado como metáfora profética del remanente que queda tras la cosecha (Isa 17:6) y de la desolación de una ciudad arruinada (Isa 27:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5586', 'spa', 'desgajar ramas — cortar las ramas altas con fuerza', 'Este verbo denominativo significa cortar ramas, específicamente la copa o parte superior de un árbol. Isaías lo emplea en un poderoso oráculo contra Asiria, declarando que el Señor mismo desgajará las ramas elevadas con fuerza aterradora. La imagen presenta a Dios como un leñador que tala el orgulloso bosque del poderío militar asirio. La forma intensiva Piel subraya el vigor y la totalidad de la acción de cortar. Esta es la única aparición bíblica del verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5587a', 'spa', 'opiniones divididas — vacilación religiosa entre lealtades opuestas', 'Este sustantivo plural describe un pensamiento dividido o escindido, utilizado en el famoso desafío de Elías en el monte Carmelo. El profeta exige saber hasta cuándo Israel ''cojeará entre dos opiniones,'' intentando servir tanto a Yahvé como a Baal simultáneamente. La imagen sugiere piernas desiguales o una postura dividida que produce un andar inestable y claudicante. La metáfora capta poderosamente el compromiso religioso y la doblez de ánimo. El contexto apoya claramente la idea de división mental y religiosa, más que una referencia literal a las piernas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5588', 'spa', 'de doble ánimo — los de lealtad dividida', 'Este adjetivo describe a personas de corazón dividido o de doble ánimo, particularmente en la devoción religiosa. El salmista declara un odio apasionado hacia tales personas tibias, amando la ley de Dios mientras desprecia a quienes la tratan con ambivalencia. El término sugiere división interna, compromiso vacilante y carácter poco fiable. El contexto religioso señala a quienes intentan mantener lealtades rivales en lugar de una fidelidad plena y sincera al pacto con Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5590', 'spa', 'Agitarse como tempestad, bramar; en formas causativas, dispersar o arrastrar como con un torbellino', 'Verbo que evoca la furia desatada de una tempestad, empleado tanto literalmente para describir mares embravecidos como figuradamente para la ira divina o la agitación humana. Los marineros de Jonás enfrentan un mar que «iba embraveciéndose más y más» (Jon 1:11, 13), e Isaías llama a la Jerusalén afligida «azotada por tempestad» (Is 54:11). En la conjugación Piel el sentido se vuelve activo: Dios dispersa a los desobedientes «con torbellino entre las naciones» (Zac 7:14), y Oseas compara a los impíos con tamo «arrastrado de la era» (Os 13:3). El cognado árabe sa''ara (''encender, inflamar'') sugiere una etimología profunda de agitación violenta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5591a', 'spa', 'Tempestad, tormenta violenta; frecuentemente figura del juicio iracundo de Dios que se abate sobre los impíos', 'Sustantivo masculino que designa una tempestad feroz o torbellino, empleado tanto en sentido literal como en una poderosa figura de la ira divina. En el oráculo repetido de Jeremías, «una tempestad arremolinada» (סַעַר מִתְחוֹלֵל) estalla sobre las cabezas de los malvados (Jer 23:19; 25:32; 30:23). Los Salmos lo utilizan para describir la fuerza abrumadora de la que el justo clama ser librado (Sal 55:8) y como instrumento con que Dios persigue a sus enemigos (Sal 83:15). Amós 1:14 lo empareja con el día de tempestad como metáfora de devastación militar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5591b', 'spa', 'Tormenta, tempestad, torbellino: vendaval violento que frecuentemente expresa poder divino, juicio o teofanía.', 'Tormenta, tempestad, torbellino: vendaval violento que frecuentemente expresa poder divino, juicio o teofanía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5592a', 'spa', 'Cuenco o vasija ritual, especialmente para uso en el templo; metafóricamente, copa de vértigo (juicio divino)', 'Término que abarca lo práctico y lo profético. En su sentido primario, סַף designa un cuenco o vasija usado en contextos rituales y domésticos: la sangre de la Pascua se recoge «en el lebrillo» para marcar los dinteles (Éx 12:22), los inventarios del templo enumeran cuencos de plata entre los utensilios sagrados (1 R 7:50; 2 R 12:13), y 2 Samuel 17:28 menciona vasijas llevadas al campamento de David. Zacarías 12:2 transforma este humilde recipiente en una metáfora dramática: Jerusalén se convierte en un «סַף רַעַל», una copa de vértigo que embriaga a las naciones sitiadores con el juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5592b', 'spa', 'Umbral, dintel inferior — la piedra o travesaño de madera en la base de una puerta, especialmente de un templo o palacio', 'Umbral, dintel inferior — la piedra o travesaño de madera en la base de una puerta, especialmente de un templo o palacio');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5593', 'spa', 'Saf — gigante filisteo muerto en Gob', 'Saf fue uno de los descendientes de los gigantes refaítas que vivían entre los filisteos. Cayó en batalla en Gob durante una de las campañas de David contra los campeones filisteos. El relato paralelo en 1 Crónicas 20:4 registra su nombre como Sipai, mostrando una variación textual típica. Estas batallas contra guerreros gigantes demostraban el conflicto continuo de David con el poderío militar filisteo y evocaban su victoria anterior sobre Goliat. El nombre aparece únicamente en estos relatos bélicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5594', 'spa', 'Lamentar, plañir, hacer duelo por los muertos; por extensión, plañidero o el acto mismo de lamentación', 'Lamentar, plañir, hacer duelo por los muertos; por extensión, plañidero o el acto mismo de lamentación');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5595', 'spa', 'Barrer, arrebatar, destruir; también añadir o amontonar; en Nifal, ser barrido o perecer.', 'Barrer, arrebatar, destruir; también añadir o amontonar; en Nifal, ser barrido o perecer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5596a', 'spa', 'unirse, agregarse a; juntarse o asociarse con un grupo', 'Verbo que expresa la idea de unirse o agregarse a otra persona o grupo, abarcando desde la asociación voluntaria hasta la petición desesperada y la adhesión involuntaria. Un descendiente sacerdotal empobrecido suplica que lo agreguen a cualquier oficio sacerdotal para sobrevivir (1 Sam 2:36), mientras David lamenta ser expulsado de la herencia del Señor (1 Sam 26:19). Proféticamente, naciones se unirán a la casa de Jacob (Is 14:1). Job 30:7 describe a marginados que se amontonan entre los arbustos. El rango semántico va desde la súplica individual hasta la incorporación colectiva a escala nacional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5596b', 'spa', 'herir con sarna — infligir enfermedad cutánea como juicio divino', 'Este verbo intensivo describe el juicio de Dios contra las mujeres orgullosas de Jerusalén mediante una enfermedad de la piel. El profeta Isaías anuncia que el Señor herirá a las hijas de Sion con sarna en la cabeza, despojándolas de su belleza y reemplazándola con humillación. La forma Piel enfatiza una acción deliberada y completa. La raíz se relaciona con el sustantivo para ''sarna'' o erupción cutánea. Esta profecía impactante apunta contra la soberbia y la vanidad que Isaías condena en el catálogo de artículos de lujo del capítulo 3.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5598', 'spa', 'Sipai — gigante filisteo, variante del nombre Saf', 'Sipai aparece en Crónicas como el nombre de un gigante filisteo muerto durante las guerras de David. Se trata del mismo individuo llamado Saf en 2 Samuel 21:18, siendo la variación del nombre algo habitual en relatos bíblicos paralelos. Era uno de varios descendientes de los refaítas que combatieron contra las fuerzas de David. El relato de Crónicas ofrece detalles ligeramente distintos al narrar los mismos enfrentamientos históricos con campeones filisteos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5599a', 'spa', 'derramamientos/rebrotes — término disputado referido a agua o crecimiento vegetal', 'Este sustantivo plural aparece en la descripción poética de Job sobre las fuerzas naturales, aunque su significado preciso sigue siendo incierto. La interpretación tradicional sugiere ''derramamientos'' de agua que arrastran el polvo de la tierra, acorde con el tema de Job sobre el poder divino que erosiona los cimientos humanos. Otros proponen ''rebrotes'' o vegetación espontánea basándose en términos hebreos afines. La dificultad textual ha generado diversas propuestas, incluida la enmienda del texto. El contexto describe procesos naturales implacables que desgastan la esperanza humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5599b', 'spa', 'rebrote espontáneo; grano que brota de granos caídos después de la cosecha sin haber sido sembrado', 'Este término agrícola se refiere al grano que crece de forma espontánea a partir de granos que cayeron accidentalmente durante la cosecha anterior. Levítico 25:5, 11 prohíbe recoger este rebrote durante el año sabático, garantizando el descanso completo de la tierra. En 2 Reyes 19:29 e Isaías 37:30, comer «lo que nace de suyo» sirve como señal de que la normalidad regresará tras la invasión de Senaquerib. El término refleja realidades agrarias antiguas donde los cultivos espontáneos podían sustentar a la población cuando era imposible sembrar de manera regular.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5600', 'spa', 'nave/embarcación — barco de navegación marítima', 'Este sustantivo designa una nave o embarcación de navegación marítima. Aparece en el relato de Jonás, donde el profeta desciende a las partes más internas del barco para dormir durante la tormenta. El término probablemente enfatiza la naturaleza cubierta o cerrada de la embarcación, revestida con tablas o provista de cubierta. Los cognados arameos confirman el significado, y el árabe tomó prestado el vocablo. Su única aparición bíblica ofrece evidencia contextual limitada, pero el escenario marítimo es inequívoco.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5601', 'spa', 'Zafiro, lapislázuli — piedra preciosa de intenso color azul muy apreciada en el arte y culto del antiguo Cercano Oriente', 'El sustantivo סַפִּיר (sappir) designa una gema de intenso color azul, muy probablemente lapislázuli y no el zafiro moderno (corindón), ya que el zafiro genuino era raro en el antiguo Cercano Oriente mientras que el lapislázuli se importaba desde Afganistán y era atesorado en toda Mesopotamia y Egipto. Bajo los pies de Dios en el Sinaí apareció ''algo semejante a un pavimento de zafiro, claro como el cielo mismo'' (Éx 24:10), y el trono divino en la visión de Ezequiel descansa sobre lo que parece ser zafiro (Ez 1:26; 10:1). La piedra figura en el pectoral del sumo sacerdote (Éx 28:18; 39:11), en la meditación de Job sobre el valor incomparable de la sabiduría (Job 28:6, 16) y en los cimientos de la ciudad escatológica (Is 54:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5603', 'spa', 'Cubrir, revestir o artesonar con madera; guardar o reservar algo', 'El verbo סָפַן describe principalmente el acto arquitectónico de cubrir o revestir una estructura con madera, especialmente de cedro. Salomón cubrió el templo con vigas (1 Re 6:9) y las salas de su palacio fueron revestidas de cedro (1 Re 7:3, 7). Jeremías condena al rey que dice «me edificaré una casa espaciosa con salas artesonadas» (Jer 22:14), y Hageo pregunta si el pueblo debe habitar en «casas artesonadas» mientras el templo yace en ruinas (Hag 1:4). Una ocurrencia singular en la bendición de Moisés (Dt 33:21) emplea la palabra con el sentido de algo «reservado» o «guardado».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5604', 'spa', 'techo/cielo raso — revestimiento interior superior de un edificio', 'Este término designa el techo o cielo raso interior de un edificio. Aparece en el relato de la construcción del templo de Salomón, describiendo cómo el interior fue revestido con cedro desde el suelo hasta el techo. La palabra indica la superficie interior superior que completa el cerramiento de la estancia. Este elemento arquitectónico era importante tanto por razones estructurales como estéticas, recibiendo el mismo tratamiento de madera de calidad que las paredes y el piso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5605', 'spa', 'estar en el umbral — servir como guardián de la puerta', 'Este verbo reflexivo significa colocarse en el umbral, sirviendo como guardián o portero. El salmista lo emplea para expresar su devoción a la casa de Dios, declarando que preferiría estar en el umbral del templo de Dios antes que habitar en las tiendas de la maldad. La imagen transmite un servicio humilde: incluso la posición más modesta en la presencia de Dios supera cualquier privilegio mundano. La forma hitpael enfatiza el posicionamiento deliberado y la permanencia voluntaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5606a', 'spa', 'Golpear, abofetear o batir palmas (manos o muslo); extendido a estrechar manos en alianza o chapotear en el agua.', 'En su esencia, un verbo de contacto físico brusco: el chasquido de palma contra palma o de mano contra muslo. Cubre todo el registro emocional del aplauso: Balac bate sus palmas con furia (Nm 24:10), las naciones aplauden en burla por la caída de Jerusalén (Lm 2:15), y Jeremías se golpea el muslo con remordimiento (Jer 31:19). Dos extensiones poco frecuentes amplían este núcleo: en Isaías 2:6 el Hifil describe el estrecharse las manos con extranjeros para sellar alianzas, y en Ezequiel 47:2 las aguas crecientes de la visión del templo llegan al punto de chapotear o vadear.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5606b', 'spa', 'bastar, ser suficiente — ser adecuado o alcanzar para un propósito', 'Este verbo significa bastar, ser suficiente o ser adecuado para un fin determinado. Ben-hadad lo emplea en su jactancia contra Acab, afirmando burlonamente que el polvo de Samaria no bastará para dar un puñado a cada uno de sus soldados, un lenguaje hiperbólico que amenaza con la destrucción total. La raíz aparece en hebreo rabínico y arameo con significados relacionados con la suficiencia y la abundancia. La única aparición bíblica sitúa el verbo en un contexto de amenaza militar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5607a', 'spa', 'abundancia/escarnio — término disputado, posiblemente palmoteo o desprecio', 'Esta palabra aparece en un pasaje difícil de Job donde Elihú advierte a Job sobre la disciplina divina. La interpretación tradicional la vincula con el palmoteo burlón o gestos de escarnio. Otros la relacionan con el sustantivo para ''suficiencia'' o ''abundancia'', advirtiendo contra la riqueza que conduce al desprecio de la corrección. Las dificultades textuales y léxicas han generado múltiples propuestas académicas, algunas sugiriendo enmienda textual. El contexto implica una advertencia contra reaccionar incorrectamente al castigo de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5607b', 'spa', 'suficiencia, abundancia — provisión adecuada', 'Este sustantivo designa suficiencia, abundancia o provisión adecuada. Zofar lo emplea al describir el destino del impío, declarando que en la plenitud de su suficiencia, la angustia lo alcanzará. La ironía es incisiva: en el preciso momento en que el malvado tiene todo lo que necesita, sobreviene la calamidad. El término enfatiza haber alcanzado un estado de provisión plena o sobreabundancia, lo que hace la reversión aún más dramática.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5608a', 'spa', 'Contar, numerar (Qal); relatar, narrar, declarar (Piel); ser contado (Nifal); ser relatado (Pual) — uniendo enumeración y narración.', 'סָפַר ilustra de manera elocuente cómo el pensamiento hebreo antiguo conectaba el contar y el relatar. La misma raíz que significa ''cuenta las estrellas'' (Gn 15:5) también significa ''contó la historia'' (Gn 24:66), como si narrar fuera una contabilidad cuidadosa de los hechos y enumerar fuera una forma de declaración. El Qal maneja la numeración, el Piel se desplaza a la narración y proclamación, y los temas pasivos (Nifal, Pual) invierten cada uno respectivamente. El cognado סֵפֶר (''libro, rollo'') confirma la vinculación de esta raíz con el registro organizado y deliberado. El español preserva admirablemente la ambigüedad hebrea con ''contar'', que abarca tanto la cuenta numérica como el relato de una historia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5608b', 'spa', 'Escriba, secretario o funcionario letrado; ya sea un oficial individual de la corte o una clase profesional de escritores.', 'Escriba, secretario o funcionario letrado; ya sea un oficial individual de la corte o una clase profesional de escritores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5609', 'spa', 'libro, registro escrito (arameo); rollo o documento oficial utilizado para documentación', 'Cognado arameo del hebreo סֵפֶר, este sustantivo designa un documento escrito, libro o registro oficial. En Esdras se refiere a los archivos reales y al libro de Moisés, mientras que en Daniel 7:10 el plural describe los libros celestiales abiertos ante el tribunal divino. El término subraya la práctica del antiguo Cercano Oriente de llevar registros meticulosos, tanto para la administración imperial como para la ley sagrada. Ya sea un decreto de Ciro o el juicio final de Dios, el סְפַר confiere autoridad documental a lo que contiene.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5610', 'spa', 'censo, enumeración — recuento oficial de personas', 'Este sustantivo del hebreo tardío significa enumeración o censo. Aparece en el relato de Crónicas sobre la organización de la fuerza laboral de Salomón, describiendo el recuento de los residentes extranjeros en Israel. El término representa el proceso administrativo formal de numerar personas para la asignación de trabajos. Su conexión con la raíz verbal ''contar'' es evidente. Este vocabulario refleja el lenguaje burocrático apropiado para los proyectos reales de construcción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5611', 'spa', 'Sefar — lugar en Arabia, punto de referencia fronterizo', 'Sefar aparece como un marcador geográfico fronterizo en la Tabla de las Naciones, definiendo el límite oriental del territorio de las tribus joctanitas en Arabia. La ubicación se ha identificado tentativamente con Ẓafār, antigua capital himyarita en el sur de Arabia, aunque esta identificación enfrenta dificultades filológicas. El nombre con sufijo direccional indica ''hacia Sefar'', mostrando que funcionaba como un punto de referencia conocido. La localización precisa sigue siendo incierta a pesar de las propuestas académicas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5612a', 'spa', 'Documento escrito: libro o rollo, carta o epístola, o certificado legal oficial como un acta de divorcio o decreto real.', 'Antiguo préstamo semítico (del acadio shipru, ''mensaje, misiva'') que se convirtió en el término hebreo primario para todo lo plasmado por escrito. Su alcance se extiende desde lo grandioso — ''el Libro de la Ley'' hallado en el templo de Josías (2 R 22:8) y ''el Libro de las Guerras del Señor'' (Nm 21:14) — hasta lo crudamente práctico: las cartas falsificadas de Jezabel (1 R 21:8) y la carta de divorcio de Deuteronomio 24:1. El español capta bien la amplitud, empleando ''libro'' para rollos sagrados e históricos, ''carta'' para correspondencia personal y ''documento'' para certificados legales. La ascendencia acadia como despacho real resplandece en las acepciones de carta y decreto, mientras que su evolución más amplia hacia ''libro'' refleja la creciente cultura literaria de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5612b', 'spa', 'en tu libro — registro divino de las lágrimas del salmista', 'Esta forma combina la preposición ''en'' con ''tu libro'', aludiendo al registro que Dios lleva de los sufrimientos humanos. El salmista apela a la atenta documentación divina de su aflicción, preguntando si sus lágrimas están anotadas en el libro celestial. La imagen presenta a Dios como quien lleva cuenta minuciosa de las experiencias humanas, especialmente de sus padecimientos. Aunque algunos estudiosos lo consideran una glosa, el pasaje refleja la teología bíblica de la atención y memoria fiel de Dios hacia las luchas de sus siervos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5613', 'spa', 'Escriba o secretario; término arameo para un funcionario letrado, usado para administradores persas y para Esdras', 'Sustantivo masculino arameo que significa escriba o secretario, presente exclusivamente en el libro de Esdras. Designa tanto a secretarios imperiales persas —como Simsai el escriba, que redactó acusaciones contra los judíos (Esd 4:8-9, 17, 23)— como al propio Esdras, descrito como «escriba versado en la ley de Moisés» (Esd 7:12, 21). Es el cognado arameo del hebreo sopher, reflejo del mundo administrativo bilingüe del período persa. Aplicado a Esdras, porta un doble significado: es a la vez un funcionario reconocido por el gobierno y un erudito de la Torá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5614', 'spa', 'Sefarad — lugar de exilio, posiblemente Sardis en Asia Menor', 'Sefarad aparece en Abdías como un lugar donde vivían exiliados de Jerusalén. Las identificaciones tradicionales van desde Sardis en Asia Menor (equiparada con la Sparda asiria) hasta localidades en Media. La tradición judía posterior la asoció con España, dando origen al término ''sefardí'' para designar a los judíos hispanos. La ubicación precisa sigue siendo debatida, siendo la Sparda (Sardis) de la inscripción de Behistún uno de los candidatos más firmes. El contexto señala una comunidad significativa de la diáspora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5615', 'spa', 'números — cantidades innumerables, más allá del cálculo humano', 'Este sustantivo plural significa números o cantidades contables. El salmista lo emplea para confesar su incapacidad de enumerar los actos justos y las liberaciones de Dios, pues exceden toda posibilidad de cómputo. El término enfatiza la cuantificación y la enumeración. Algunos testimonios textuales leen aquí una forma relacionada con ''libros'' o ''escritos'', pero el contexto de lo innumerable encaja bien con ''números''. El vocabulario expresa la abrumadora abundancia de las misericordias divinas, que sobrepasan todo cálculo humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5616', 'spa', 'los sefarvitas — habitantes de Sefarvaim reasentados en Samaria', 'Este gentilicio designa a los habitantes de Sefarvaim, ciudad cuyos pobladores fueron trasladados a Samaria por los asirios tras la caída del reino del norte. Los sefarvitas trajeron consigo sus prácticas religiosas paganas, incluyendo el horrendo culto a Adramélec y Anamélec que involucraba sacrificios de niños. Su presencia en Samaria contribuyó al sincretismo religioso que caracterizó a la comunidad samaritana posterior al exilio. La ubicación exacta de su patria, Sefarvaim, sigue siendo objeto de debate entre los estudiosos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5617', 'spa', 'Sefarvaim; ciudad mesopotámica conquistada por Asiria, cuyos habitantes fueron reasentados en Samaria tras el exilio del norte', 'Nombre propio en forma dual que designa la ciudad mesopotámica de Sefarvaim, identificada tradicionalmente con la ciudad doble de Sippar, a orillas del Éufrates entre Bagdad y Babilonia. Aparece en dos contextos históricos: el reasentamiento asirio de pueblos extranjeros en Samaria (2 R 17:24, 31), y las jactancias de los emisarios asirios que desafían la confianza de Jerusalén en Dios (2 R 18:34; 19:13; Is 36:19; 37:13). La terminación dual podría reflejar las dos mitades de la ciudad — Sippar de Shamash y Sippar de Anunitu — situadas a ambos lados de un canal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5619', 'spa', 'Apedrear (como ejecución judicial); desempedrar un campo (Piel); arrojar piedras contra alguien con hostilidad (Piel intensivo)', 'Apedrear (como ejecución judicial); desempedrar un campo (Piel); arrojar piedras contra alguien con hostilidad (Piel intensivo)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5620', 'spa', 'malhumorado, resentido; en un estado de disgusto obstinado y sombrío', 'Este adjetivo describe un estado emocional sombrío, resentido y hosco: un disgusto obstinado que se repliega hacia adentro. El rey Acab regresó a casa «resentido y malhumorado» (1 Reyes 20:43) después de que el profeta lo condenara por liberar a Ben-adad. En 1 Reyes 21:4-5 se repite el patrón: Acab se acuesta «malhumorado y resentido» porque Nabot rehusó venderle su viña, y Jezabel le pregunta: «¿Por qué está tu espíritu tan sombrío?» La palabra capta esa combinación tóxica de deseo frustrado, orgullo herido y retraimiento rencoroso: rechazar consuelo, alimentar el agravio, rumiar en un sentimiento de derecho defraudado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5621', 'spa', 'rebeldes/cardos — término disputado, posiblemente oposición espinosa', 'Esta palabra aparece en el llamamiento divino a Ezequiel, advirtiendo al profeta sobre su audiencia. La interpretación tradicional ve ''rebeldes'' o ''contumaces'' basándose en raíces arameas de contradicción y desafío. Sin embargo, su emparejamiento con otro término incierto ha llevado a algunos a leer ambos como ''cardos y espinos'', enfatizando una oposición hostil y punzante. Las versiones antiguas muestran confusión: unas leen participios y otras adoptan la lectura botánica. El contexto indica claramente una resistencia feroz al mensaje de Ezequiel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5623', 'spa', 'Sargón — rey asirio, conquistador de Samaria', 'Sargón II reinó sobre Asiria del 722 al 705 a.C. y completó la conquista de Samaria iniciada por su predecesor. Aunque solo se le menciona una vez en la Biblia, los registros asirios documentan ampliamente su reinado y campañas militares. Su nombre acadio Šarru-kēnu significa ''el rey es legítimo'', posiblemente reflejando las circunstancias políticas de su ascensión. Isaías lo menciona en relación con el asedio de Asdod, demostrando el poder asirio extendiéndose hasta territorio filisteo. Fue padre del célebre Senaquerib.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5625', 'spa', 'el seredita — clan descendiente de Sered', 'Este adjetivo gentilicio designa a los miembros del clan seredita, descendientes de Sered, hijo de Zabulón. El término aparece en el censo del desierto registrado en Números, donde los clanes de cada tribu se enumeran con fines de organización militar. Los sereditas formaban uno de los tres grupos familiares zabulonitas. Esta precisión genealógica servía tanto para la administración de la comunidad en el desierto como para preservar la memoria tribal de cara al futuro reparto de la tierra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5626', 'spa', 'Sirá — cisterna o topónimo cerca de Hebrón', 'Sirá aparece como referencia geográfica — específicamente una cisterna o pozo — donde los mensajeros de Joab encontraron a Abner y lo trajeron de vuelta a Hebrón con engaño para asesinarlo. El nombre podría derivar de una raíz que significa ''apartarse'' o relacionarse con ''olla/caldero''. Su cercanía a Hebrón la hacía un lugar conveniente para la emboscada. Este detalle geográfico cobra importancia en la compleja historia política de David, ya que el asesinato de Abner creó serias complicaciones para la unificación del reino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5627', 'spa', 'Rebelión, revuelta, apostasía; cesación, retirada', 'El sustantivo סָרָה, de la raíz סור (''apartarse''), designa el acto de apartarse de Dios o de lo recto. En Deuteronomio y los profetas es un término teológico de gran peso: predicar rebelión contra el SEÑOR (Dt 13:5), acumular revuelta sobre revuelta (Is 1:5; 31:6) y hablar falsedad y opresión (Is 59:13). Jeremías lo emplea para los falsos profetas que hablan rebelión (Jer 28:16; 29:32). Una ocurrencia en Isaías 14:6 conserva un sentido más antiguo y neutro — una cesación o retirada de la opresión — donde el apartarse no es defección moral sino el cese de una persecución implacable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5628', 'spa', 'Extenderse, colgar, desparramarse; tenderse con exceso indolente; echarse a perder, pudrirse.', 'Verbo que describe originalmente algo que se extiende o sobrepasa sus límites propios, con imágenes vívidas en sus tres acepciones. Las cortinas del tabernáculo ''cuelgan'' sobre los costados (Éx 26:12-13), y la vid de Ezequiel ''extiende'' sus ramas (Ez 17:6). Amós transforma la imagen física en crítica moral: los ricos ''se desparraman'' en sus lechos de marfil (Am 6:4, 7), donde ''los extendidos'' conserva el sentido literal de ''tendidos'' mientras el contexto profético aporta la denuncia. En Jer 49:7, el Nifal pasa a la descomposición: la sabiduría ''se ha podrido'', evocando algo que fue bueno y se echó a perder.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5629', 'spa', 'excedente/voladizo — porción que se extiende más allá', 'Este sustantivo designa lo que sobra o se extiende más allá de una medida, utilizado específicamente para la cubierta de la tienda del tabernáculo que colgaba por debajo de la estructura. El término aparece en las instrucciones de Éxodo para la tienda de reunión, describiendo cómo el largo sobrante de la cubierta de pelo de cabra debía caer a los lados. El concepto central es el exceso o sobrante, lo que se extiende más allá de la medida necesaria. Este detalle arquitectónico aseguraba una cobertura completa y protección contra la intemperie.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5631', 'spa', 'Eunuco, oficial de la corte; varón castrado al servicio de la casa real, o en sentido más amplio, un alto funcionario real', 'Eunuco, oficial de la corte; varón castrado al servicio de la casa real, o en sentido más amplio, un alto funcionario real');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5632', 'spa', 'jefe, alto comisionado; funcionario administrativo de alto rango (préstamo arameo del persa)', 'Tomado del persa (sar, ''cabeza, jefe''), este término arameo designa a un alto comisionado o prefecto gubernamental. Las cinco apariciones se concentran en Daniel 6, donde tres סָרְכִין son nombrados sobre los 120 sátrapas del imperio medopersa. Daniel mismo es elevado entre ellos, provocando la envidia que desencadena el episodio del foso de los leones. El vocablo refleja el vocabulario burocrático que entró al arameo durante el período aqueménida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5633a', 'spa', 'Seren -- seor, tirano; ttulo distintivo de cada uno de los cinco gobernantes de las ciudades-estado filisteas. Prstamo lingstico al hebreo, probableme', 'Seren -- seor, tirano; ttulo distintivo de cada uno de los cinco gobernantes de las ciudades-estado filisteas. Prstamo lingstico al hebreo, probablemente de una lengua presemica egea o anatolia, usado exclusivamente para los gobernantes de las cinco ciudades-estado filisteas: Gaza, Ascaln, Asdod, Ecrn y Gat. A diferencia de los trminos hebreos ms amplios para ''rey'' o ''prncipe'', seren es un ttulo poltico tcnico reservado para la gobernanza filistea, que aparece solo en plural. La palabra podra estar emparentada con el griego tyrannos. Estos seores actan colectivamente en narrativas clave: negociando con Dalila contra Sansn (Jue 16), devolviendo el arca capturada (1 Sam 5-6) y rechazando el servicio de David (1 Cr 12:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5633b', 'spa', 'eje (de carro o base con ruedas)', 'Se refiere a los ejes de bronce que permitían girar las ruedas de las bases móviles del templo de Salomón. Este término técnico poco frecuente aparece únicamente en la descripción de las diez bases de bronce fabricadas para el templo, cada una equipada con ruedas montadas sobre ejes de bronce. La palabra tiene un cognado arameo, lo cual sugiere que podría ser un préstamo léxico del vocabulario especializado en metalurgia. Las versiones antiguas tuvieron dificultades para traducirlo, y el griego lo vertió libremente como ''uniones''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5634', 'spa', 'rama, ramaje (de un gran árbol)', 'Designa las ramas extendidas de un gran árbol en la alegoría de Ezequiel sobre el Faraón. La palabra aparece exclusivamente en Ezequiel 31, donde Egipto se representa como un cedro imponente cuyas ramas se multiplicaron más allá de cualquier otro árbol. El término incluye una ''r'' infijada como marcador morfológico, similar a formas arameas, lo cual indica su carácter lingüístico tardío. La imagen transmite el poder imperial que extiende su influencia como ramas frondosas alimentadas por aguas abundantes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5635', 'spa', 'quemar, el que quema (forma participial)', 'Forma participial del verbo común «quemar», que aparece en la visión de juicio de Amós, donde un pariente viene a incinerar los cuerpos de los muertos. El contexto es de peste o desastre militar tan severo que el entierro normal resulta imposible y los cadáveres deben ser cremados, práctica inusual en Israel. El que quema entra a la casa para retirar los restos en secreto, reflejando la magnitud de la catástrofe divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5636', 'spa', 'zarza, ortiga (planta espinosa del desierto)', 'Planta espinosa e indeseable que contrasta con el fragante mirto en la visión de restauración de Isaías. Cuando Dios renueve la tierra, la zarza despreciable será reemplazada por el noble mirto. Las versiones antiguas la identificaron como ortiga u otra hierba nociva similar. Aunque su identidad botánica precisa es incierta, el contraste simbólico es claro: las espinas del juicio frente a la belleza de la bendición divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5637', 'spa', 'Ser obstinado, rebelde -- resistir la autoridad con desafo, especialmente la negativa obstinada de Israel a obedecer a Dios o la rebelda de un hijo co', 'Ser obstinado, rebelde -- resistir la autoridad con desafo, especialmente la negativa obstinada de Israel a obedecer a Dios o la rebelda de un hijo contra sus padres. Verbo que expresa desafo obstinado y resistencia deliberada a la autoridad legtima. Oseas 4:16 ofrece el smil memorable: ''como novilla indmita, Israel se resiste'', comparando la intransigencia espiritual de la nacin con un animal que rehsa el yugo. La forma participial sorer aparece como adjetivo en la ley del hijo rebelde (Deuteronomio 21:18, 20) y en las acusaciones profticas contra Israel como ''hijos rebeldes'' (Isaas 30:1; 65:2). Incluso Proverbios 7:11 lo aplica a la mujer descarriada que es ''alborotadora y rebelde''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5639', 'spa', 'Setur (nombre propio: «oculto, protegido»)', 'Nombre del espía de la tribu de Aser enviado por Moisés a explorar la tierra de Canaán. Uno de los doce representantes tribales en Números 13, Setur se unió al informe mayoritario que desalentó a Israel de entrar en la tierra prometida. Su nombre puede significar «oculto» o «protegido», derivado de la raíz que significa esconder o encubrir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5640a', 'spa', 'Tapar, cerrar, sellar o mantener cerrado; por extensión, ocultar o guardar en secreto (de palabras proféticas o conocimiento escondido).', 'Verbo cuyo sentido físico central —tapar fuentes de agua— se extiende al ámbito del secreto y la ocultación divina. En 2 Reyes 3:19 y 2 Crónicas 32 describe la táctica militar de bloquear manantiales y pozos. Pero en Daniel 8:26 y 12:4 adquiere peso profético: «sella la visión», donde la clausura se convierte en ocultación hasta el tiempo señalado. El participio pasivo en Salmo 51:6 («en lo secreto») muestra cómo el bloqueo físico se transformó en metáfora de la sabiduría oculta de Dios. El español capta bien ambos polos: «cegar» para el bloqueo físico de aguas y «cerrar/sellar» para las palabras proféticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5640b', 'spa', 'bloquear, excluir (especialmente la oración)', 'Verbo del hebreo tardío que significa tapar o excluir, usado de manera única en Lamentaciones, donde el poeta se lamenta de que Dios ha bloqueado su oración para que no llegue al cielo. Es una variante de la raíz más común que significa «tapar», pero aquí conlleva el sentido de rechazo divino. Algunos eruditos sugieren que podría estar relacionado con raíces árabes que significan frustrar o decepcionar. Su rareza enfatiza la intensidad del bloqueo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5641', 'spa', 'Esconder, ocultar; reflexivamente esconderse; causativamente ocultar a otro; de Dios que esconde su rostro en juicio o disciplina.', 'Esconder, ocultar; reflexivamente esconderse; causativamente ocultar a otro; de Dios que esconde su rostro en juicio o disciplina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5642a', 'spa', 'cosas ocultas (forma participial aramea)', 'Participio pasivo arameo que designa las cosas encubiertas o mantenidas en secreto. Daniel emplea este término al alabar a Dios, quien «revela lo profundo y lo oculto» y conoce lo que yace en las tinieblas. La palabra subraya el contraste entre la omnisciencia divina y la limitación humana: lo que está velado para los mortales permanece abierto ante la mirada de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5642b', 'spa', 'destruir, derribar (arameo)', 'Verbo arameo que significa destruir o demoler, emparentado con el siríaco y relacionado con la raíz hebrea para derribar. En Esdras describe la destrucción del templo de Salomón a manos de Nabucodonosor. La sección aramea de Esdras emplea este término para narrar la causa histórica de la ruina del templo antes de relatar su reconstrucción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5643a', 'spa', 'Secreto, escondite, refugio — acción encubierta hecha ''en secreto'' o lugar concreto de ocultamiento y amparo', 'Secreto, escondite, refugio — acción encubierta hecha ''en secreto'' o lugar concreto de ocultamiento y amparo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5643b', 'spa', 'refugio, protección (contra el peligro)', 'Sustantivo femenino poco frecuente que significa refugio o protección, usado con ironía en el cántico de Moisés donde se burla de los falsos dioses de los enemigos de Israel. «¡Que ellos sean refugio sobre vosotros!», dice con sarcasmo, desafiando a esos ídolos inertes a brindar la seguridad que sus adoradores esperan. El término normalmente connota amparo, pero aquí destila desdén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5644', 'spa', 'Sitri (nombre propio: ''protección de Yah'')', 'Nombre levítico de la familia de Coat que aparece en los registros genealógicos de Éxodo. Sitri era primo de Moisés y Aarón, descendiente de Uziel. El nombre probablemente significa «mi protección» o «Yah es mi refugio», incorporando el nombre divino. Las versiones griegas lo transliteran de diversas formas: Seghri, Sethri o Setri.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5645', 'spa', 'Nube oscura o masa de nubes; también densidad espesa o matorral de vegetación usado como cobertura', 'Nube oscura o masa de nubes; también densidad espesa o matorral de vegetación usado como cobertura');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5646', 'spa', 'término arquitectónico de significado incierto; posiblemente umbral, dosel o viga gruesa', 'Este sustantivo arquitectónico aparece tres veces, pero su significado preciso sigue siendo incierto. En 1 Reyes 7:6 se menciona junto a «columnas» en la descripción de la construcción del palacio de Salomón. Ezequiel 41:25-26 lo utiliza dos veces en la visión del templo: «un dosel de madera delante del pórtico» y «los doseles» en las cámaras laterales. Las versiones antiguas y los eruditos modernos proponen diversos significados: umbral, viga gruesa, voladizo o dosel. La incertidumbre refleja nuestro conocimiento limitado de la terminología arquitectónica antigua. Lo que queda claro es que se trataba de un elemento estructural de madera asociado a entradas o pórticos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5647', 'spa', 'Trabajar, servir, adorar, labrar o esclavizar; abarca la devoción religiosa, el servicio personal, la labor agrícola y la servidumbre forzada.', 'Pocos verbos hebreos revelan la integración antigua de lo sagrado y lo cotidiano tan vívidamente como עָבַד. La misma raíz que describe a Adán labrando el huerto (Gn 2:15) describe también a Israel adorando a Dios (Éx 10:26) y al faraón esclavizando a una nación (Éx 1:13). El árabe preserva este espectro con tres raíces distintas — عبد para adoración, خدم para servicio personal y عمل para labor — dejando al descubierto distinciones semánticas que el hebreo reúne en una sola. Del campo al templo y al campo de trabajos forzados, עָבַד traza el espectro completo del deber humano, la devoción y la subyugación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5648', 'spa', 'Hacer, realizar, ejecutar; en voz pasiva, ser hecho o llevado a cabo; también construir, producir y celebrar una festividad', 'Hacer, realizar, ejecutar; en voz pasiva, ser hecho o llevado a cabo; también construir, producir y celebrar una festividad');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5649', 'spa', 'Siervo, esclavo (arameo); usado para cortesanos reales y siervos de Dios en Daniel y Esdras.', 'Cognado arameo del hebreo eved (''siervo, esclavo''), que aparece en las escenas cortesanas de Daniel y la correspondencia administrativa de Esdras. Designa tanto a siervos humanos del rey — ''somos tus siervos'' (Esd 4:11; Dn 2:4, 7) — como a siervos de Dios, cuando Daniel es llamado ''siervo del Dios viviente'' (Dn 6:21) y Sadrac, Mesac y Abednego son reconocidos como siervos de Dios (Dn 3:26, 28). Las traducciones lo vierten uniformemente con terminología de servidumbre: español siervo/siervos, alemán Knecht, reflejando el significado constante en ambos registros, el real y el teológico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5650', 'spa', 'Siervo, servidor, súbdito; esclavo; título honorífico ''siervo de Dios'' para patriarcas, profetas y reyes', 'El sustantivo hebreo עֶבֶד abarca un espectro social que va desde el cortesano real hasta el esclavo, y asciende hasta convertirse en uno de los títulos honoríficos más elevados de la Escritura. En su uso más frecuente (723 apariciones), designa a cualquier persona que sirve a otra: un asistente doméstico, un funcionario del rey, un oficial militar, o un hablante que emplea ''tu siervo'' como pronombre cortés en primera persona. El sentido de servidumbre involuntaria (63 apariciones) se distingue en contextos legales como Éxodo 21 y Levítico 25. Notablemente, עֶבֶד se convierte en título divino: ''Mi siervo Moisés'', ''Mi siervo David'', ''Mi siervo Job'', un honorífico que en los Cánticos del Siervo de Isaías (Is 42-53) adquiere peso mesiánico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5651', 'spa', 'Ebed («siervo»), nombre propio de dos personajes: el padre de Gaal en Siquem y un compañero de Esdras', 'Ebed (עֶבֶד) significa «siervo [de Dios]», un nombre teofórico análogo a los nombres árabes compuestos con عبد. Dos personajes llevan este nombre: el padre de Gaal, quien encabezó una efímera revuelta contra Abimelec en Siquem (Jue 9:26-35), y un jefe de clan que regresó con Esdras desde Babilonia (Esd 8:6). La Septuaginta transcribe el nombre de diversas formas, como Ioabel y Obet, reflejando distintas tradiciones de transliteración. La sencillez del nombre —simplemente «siervo»— es característica de las convenciones onomásticas semíticas occidentales que expresan piedad mediante la sumisión a la deidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5652', 'spa', 'obras, acciones (forma plural aramea)', 'Préstamo arameo que significa «obras» o «acciones», empleado en la reflexión filosófica de Eclesiastés sobre la soberanía divina y la ignorancia humana. La forma plural con morfología aramea aparece en un contexto de incertidumbre: «los justos y los sabios y sus obras están en la mano de Dios», pero el ser humano no puede saber qué le depara el futuro. Este rasgo lingüístico tardío sitúa a Eclesiastés en el período postexílico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5654', 'spa', 'Obed-Edom — el geteo que albergó el Arca, y porteros y músicos levíticos que llevaron el mismo nombre', 'Obed-Edom — el geteo que albergó el Arca, y porteros y músicos levíticos que llevaron el mismo nombre');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5655', 'spa', 'Avdeel (nombre propio: ''siervo de El'')', 'Nombre propio que significa ''siervo de El (Dios)'', perteneciente a un miembro de la nobleza de Judá en tiempos de Jeremías. El hijo de Avdeel, Selemías, fue uno de los oficiales que el rey Joacim envió a arrestar a Jeremías y a Baruc tras la lectura del rollo profético. Este tipo de nombres teofóricos, que combinan ''siervo'' con un elemento divino, eran frecuentes en las culturas semíticas de la antigüedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5656', 'spa', 'Labor, servicio o ministerio — especialmente el servicio cultual del tabernáculo/templo, pero también deber general, trabajo manual y servidumbre opresiva.', 'Una de las palabras más versátiles del hebreo bíblico para el trabajo, עֲבֹדָה abarca el espectro completo desde el ministerio sagrado hasta el trabajo esclavo. En su uso dominante (~93 veces), denota el servicio cultual del tabernáculo y del templo: las tareas de los levitas de transportar, montar y custodiar, descritas a lo largo de Números y Crónicas. Más allá del santuario, cubre el servicio general prestado a reyes o comunidades (Éx 12:25-26), el trabajo agrícola y artesanal ordinario (Éx 1:14; Sal 104:23) y, en su extremo más oscuro, la servidumbre aplastante de la esclavitud en Egipto (Éx 6:6, 9). El árabe distingue خدمة (servicio) de عبودية (servidumbre), y el suajili separa utumishi (ministerio) de utumwa (esclavitud), revelando la misma estructura semántica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5658', 'spa', 'Abdón; nombre propio de un juez israelita, varios individuos y una ciudad levítica en Aser.', 'Nombre propio con referentes tanto personales como geográficos. El más destacado es Abdón hijo de Hilel el piratonita, quien juzgó a Israel durante ocho años (Jue 12:13, 15), célebre por sus cuarenta hijos y treinta nietos que cabalgaban sobre setenta asnos. El nombre pertenece también a un benjaminita en la genealogía de Saúl (1 Cr 8:23; 8:30; 9:36) y a un cortesano del rey Josías (2 Cr 34:20). Geográficamente, Abdón era una ciudad levítica en el territorio de Aser (Jos 21:30; 1 Cr 6:74). Todas las traducciones conservan el nombre fonéticamente: español Abdón, francés Abdon, alemán Abdon.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5659', 'spa', 'servidumbre, esclavitud; estado de servicio forzado o sometimiento', 'Este sustantivo femenino designa servidumbre, esclavitud o cautiverio: la condición de estar bajo servicio obligatorio. Esdras 9:8-9 lo emplea dos veces: Dios «no nos ha abandonado en nuestra servidumbre» y ha «extendido su misericordia ante los reyes de Persia, para darnos algo de alivio... y sostenernos en nuestra servidumbre». Aun sirviendo a reyes extranjeros, Dios provee gracia. Nehemías 9:17 contrasta la rebeldía de Israel con el carácter de Dios: en lugar de abandonarlos, Dios permaneció perdonador. La palabra transmite el peso del servicio obligatorio, ya sea la esclavitud de Egipto o la sujeción a Persia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5660', 'spa', 'Nombre propio que significa ''siervo de Yah'' o ''mi siervo''; llevado por un levita y un hombre con esposa extranjera', 'עַבְדִּי aparece en Crónicas y Esdras como nombre de dos individuos distintos. El nombre probablemente deriva de la raíz que significa ''siervo'', con un elemento teofórico. Uno de ellos fue un levita del linaje documentado en Crónicas, mientras que el otro figura en la lista de Esdras entre quienes habían tomado esposas extranjeras durante el exilio. Las diversas traducciones muestran patrones de transliteración consistentes, y algunas versiones preservan directamente la forma hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5661', 'spa', 'Abdiel (nombre propio: ''siervo de El'')', 'Nombre gadita que significa ''siervo de El'', registrado en las genealogías de las tribus de Transjordania. Abdiel fue antepasado de Buz, uno de los jefes de la tribu de Gad. Al igual que el nombre similar Avdeel, esta forma teofórica aparece ampliamente en inscripciones del semítico noroccidental procedentes de Fenicia, Nabatea y Arabia meridional, lo cual testimonia la práctica común de nombrar a los hijos como devotos del Dios altísimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5662', 'spa', 'Abdas, nombre propio que significa ''siervo de Yahv'', llevado por al menos doce individuos en las Escrituras. Uno de los nombres teofricos ms comunes e', 'Abdas, nombre propio que significa ''siervo de Yahv'', llevado por al menos doce individuos en las Escrituras. Uno de los nombres teofricos ms comunes en la Biblia hebrea, que significa ''siervo de Yahv''. Su portador ms destacado es el mayordomo del palacio del rey Acab, quien arriesg su vida escondiendo a cien profetas de la persecucin de Jezabel (1 Re 18:3-16). El nombre pertenece tambin al profeta cuyo breve libro pronuncia juicio contra Edom (Abd 1), a un descendiente de David (1 Cr 3:21), jefes tribales, levitas, porteros y diversos funcionarios a lo largo de Crnicas. Dos variantes ortogrficas -- Ovadyahu y Ovadyah -- se alternan a lo largo del texto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5663', 'spa', 'Ebed-Melec — ''siervo del rey,'' oficial etíope de la corte que rescató a Jeremías de la cisterna', 'El nombre עֶבֶד מֶלֶךְ (Ebed-Melec) significa ''siervo del rey'' y pertenece a un oficial cusita (etíope) de la corte del rey Sedequías. Cuando Jeremías fue arrojado a una cisterna fangosa para que muriera, Ebed-Melec pidió audazmente al rey permiso para rescatarlo y luego bajó con cuidado trapos viejos y cuerdas para no lastimar la piel del profeta (Jer 38:7-13). En gratitud, Dios envió un oráculo personal por medio de Jeremías prometiendo a Ebed-Melec liberación cuando Jerusalén cayera (Jer 39:15-18). Su historia constituye uno de los retratos más impactantes de valentía moral proveniente de un lugar inesperado: un extranjero que temió a Dios más que los príncipes de Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5665', 'spa', 'Abed-nego; nombre babilónico dado a Azarías, uno de los tres compañeros de Daniel en el relato del horno de fuego.', 'Nombre cortesano babilónico asignado a Azarías, uno de los cuatro jóvenes judíos deportados al palacio de Nabucodonosor (Dn 1:7; 2:17). El nombre probablemente significa «siervo de Nebo» (la divinidad babilónica de la sabiduría), aunque su etimología exacta es discutida, ya que la forma esperada sería Abed-Nebo. Junto con Sadrac y Mesac, Abed-nego es puesto al frente de los asuntos de la provincia de Babilonia (Dn 2:49) y luego se niega célebremente a adorar la estatua de oro, sobreviviendo al horno de fuego ardiente por liberación divina (Dn 3:12-30). La grafía aramea «Abed Nego» aparece de manera uniforme en las catorce apariciones en Daniel 2-3.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5666', 'spa', 'Ser grueso, gordo o tosco; usado para grosor físico y metafóricamente para insensibilidad espiritual', 'Este verbo abarca tanto el grosor físico como la torpeza metafórica. En la célebre comparación de 1 Reyes 12:10, los consejeros de Roboam presumen que su dedo meñique es más grueso que la cintura de su padre, una imagen vívida de poder e intimidación. En Deuteronomio 32:15, la misma raíz describe a Israel volviéndose ''grueso'' por la prosperidad, como un animal sobrealimentado que se torna rebelde. Los cognados en arameo y árabe sugieren hinchazón, densidad e incluso estupidez, mostrando cómo el grosor físico se desliza hacia la torpeza moral en las lenguas semíticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5667', 'spa', 'prenda, garantía; objeto entregado como colateral por una deuda', 'Este sustantivo designa un objeto entregado como garantía o colateral de un préstamo. Deuteronomio 24:10-13 regula la toma de prendas, exigiendo que los acreedores respeten la dignidad de los deudores: el acreedor no debe entrar en la casa del deudor para apoderarse de la prenda, y si esta es un manto, debe devolverlo antes del atardecer para que el pobre pueda dormir con él. Esta legislación protege al vulnerable sin dejar de reconocer la legitimidad del colateral en las transacciones de préstamo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5668', 'spa', 'Por causa de, a causa de; para que, a fin de que — partícula prepositiva que expresa causa, beneficio o propósito.', 'Por causa de, a causa de; para que, a fin de que — partícula prepositiva que expresa causa, beneficio o propósito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5670', 'spa', 'Prestar con prenda o tomar prestado con garantía; transacciones de préstamo con empeño en Israel', 'El verbo denominativo עָבַט abarca los dos lados de un préstamo garantizado con prenda en la legislación israelita antigua. En sus formas Hifil (causativas) describe la acción de prestar —hacer que otro entregue una prenda—, como en la promesa de que Israel «prestará a muchas naciones pero no tomará prestado» (Dt 15:6). En su forma Qal adopta la perspectiva del deudor: tomar una prenda de alguien o pedir prestado con garantía, según se regula en Dt 24:10. Todo su campo semántico gira en torno a la legislación deuteronómica sobre prácticas justas de préstamo entre compatriotas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5671', 'spa', 'Prendas gravosas, deuda aplastante (plural intensivo)', 'Sustantivo intensivo que designa una carga abrumadora de prendas o deudas, empleado en el oráculo de ayes de Habacuc contra el opresor. El profeta utiliza un lenguaje vívido para describir al conquistador arrogante que ''se carga de prendas'' tomadas de sus víctimas. La forma hebrea intensifica la idea de peso y acumulación, retratando al impío sepultado bajo la masa de las garantías que ha extorsionado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5672', 'spa', 'grosor; la dimensión de espesor o profundidad, especialmente de objetos sólidos', 'Este sustantivo designa el grosor o la dimensión de profundidad de objetos macizos. Describe el espesor del mar de bronce fundido en el templo de Salomón (1 Reyes 7:26, 2 Crónicas 4:5), el grosor de una columna (Jeremías 52:21) y, metafóricamente, el «grosor de las protuberancias de los escudos» en Job 15:26, simbolizando una actitud de arrogante desafío. El término también podría aparecer en Éxodo 19:9, si se enmienda בְּעַב הֶעָנָן a בַּעֲבִי («en la espesura de la nube»).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5673', 'spa', 'Obra, servicio o función administrativa; sustantivo arameo para labor en la construcción del templo o administración gubernamental (Daniel, Esdras).', 'El sustantivo femenino arameo עֲבִידָה (avidá) designa obra, servicio o función administrativa, cognado del hebreo עֲבֹדָה. Aparece exclusivamente en las secciones arameas de Esdras y Daniel, abarcando tanto el trabajo físico de reconstrucción del templo de Jerusalén (Esdras 4:24; 5:8; 6:7) como la administración gubernamental bajo Nabucodonosor (Dan 2:49; 3:12). Su última aparición se refiere al servicio ritual de Dios organizado por turnos sacerdotales (Esdras 6:18). Las glosas multilingües confirman este espectro semántico: español ''servicio/obra'', francés ''travail/service'', apuntando a una labor organizada e intencional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5674a', 'spa', 'Pasar, atravesar, cruzar (un límite, río); pasar de largo; cesar; transgredir; hacer pasar; quitar, remover.', 'Con 552 ocurrencias, este verbo es central en la narrativa y la ley bíblicas, pues describe el movimiento a través del espacio y el cruce de fronteras tanto físicas como morales. Abraham pasa por Canaán (Gn 12:6), Israel cruza el Jordán (Jos 3), ejércitos vadean ríos, viajeros pasan de largo por los caminos, el tiempo transcurre y las estaciones acaban, los pactos se transgreden, las ofrendas se presentan, las proclamas se difunden por los campamentos y las propiedades se transfieren. El Qal básico significa ''pasar'' o ''cruzar'', el Hifil causativo ''hacer cruzar'' o ''quitar'', y el Piel tiene usos poco frecuentes. Los significados especializados incluyen transgredir mandamientos, hacer pasar hijos ''por el fuego'' a ídolos y emitir decretos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5674b', 'spa', 'Enfurecerse o encolerizarse (Hitpael); actuar con arrogancia o pasar de largo en desafío.', 'Un verbo denominativo en Hitpael que expresa una ira intensa y reflexiva, literalmente ''provocarse a sí mismo hasta la furia''. Se predica mayormente de Dios: en el Salmo 78:21 Yahvé ''se encolerizó'' ante la incredulidad de Israel, y en Deuteronomio 3:26 ''se enojó'' con Moisés por causa del pueblo. Proverbios 14:16 lo aplica a la arrogancia humana: el necio ''se enfurece'' y es confiado en sí mismo. Una aparición en Proverbios 26:17 conserva el sentido antiguo del Qal de ''pasar de largo'', donde un transeúnte se entromete en una disputa ajena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5675', 'spa', 'Allende, la region de enfrente; sustantivo arameo usado en la frase ''Allende el Rio'' para la provincia transeufratica.', 'Sustantivo arameo cognado del hebreo עֵבֶר, que significa ''la region del otro lado'' o ''mas alla''. En el uso biblico aparece exclusivamente en la frase administrativa עֲבַר נַהֲרָה (''Allende el Rio''), designacion oficial persa para la satrapia al oeste del Eufrates que abarcaba Siria, Fenicia y Palestina. Las catorce apariciones se concentran en Esdras 4-7, donde los funcionarios persas Tatnai y Setar-boznai, gobernadores de ''Allende el Rio'', mantienen correspondencia con la corte real acerca de la reconstruccion del templo de Jerusalen. La frase refleja la geografia burocratica imperial, semejante al arabe ''ma wara al-nahr'' y al uso administrativo acadio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5676', 'spa', 'La región al otro lado o más allá (de un río o frontera); un lado, flanco o dirección relativa a un objeto; plural: lados, bordes.', 'La región al otro lado o más allá (de un río o frontera); un lado, flanco o dirección relativa a un objeto; plural: lados, bordes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5677', 'spa', 'Eber, descendiente de Sem por linea de Arfaxad y ancestro tradicional de los pueblos hebreos.', 'עֵבֶר (Eber) es el bisnieto de Sem y padre de Peleg y Joctan, situado en la Tabla de las Naciones como ancestro eponimo de los hebreos (Gn 10:21, 24-25; 11:14-17). Sem es llamado ''padre de todos los hijos de Eber'', expresion que abarca tanto la linea abrahamica por medio de Peleg como las tribus arabicas por medio de Joctan. El Cronista conserva la misma genealogia (1 Cr 1:18-19, 25), mientras que el oraculo de Balaam advierte enigmaticamente que naves de Quitim afligiran a Eber (Nm 24:24), posiblemente refiriendose a ''los hebreos'' como colectivo. Un sacerdote postexilico tambien lleva este nombre (Neh 12:20). El espanol ''Heber'' y el griego Εβερ reflejan la vocalizacion antigua de la Septuaginta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5678', 'spa', 'Ira, furor, rabia desbordante (especialmente divina); arrogancia o exceso insolente; estallidos o torrentes de cólera', 'Ira, furor, rabia desbordante (especialmente divina); arrogancia o exceso insolente; estallidos o torrentes de cólera');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5680', 'spa', 'Hebreo; adjetivo y sustantivo gentilicio que designa a los miembros del pueblo israelita/abrahámico, en masculino o femenino', 'Hebreo; adjetivo y sustantivo gentilicio que designa a los miembros del pueblo israelita/abrahámico, en masculino o femenino');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5681', 'spa', 'Ibrí (nombre propio: ''hebreo'' o posible variante textual)', 'Nombre levítico que aparece en las listas genealógicas de 1 Crónicas, donde la segunda ocurrencia podría ser una variante textual o un individuo distinto. El nombre es idéntico en forma al gentilicio ''hebreo'', pero aquí funciona como nombre propio. Los manuscritos griegos presentan una variación considerable, transliterándolo como Abai, Obdi o Abaria, lo que refleja incertidumbre temprana sobre la lectura correcta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5682', 'spa', 'Abarim; región montañosa al noroeste de Moab, al noreste del mar Muerto, que incluye el monte Nebo', 'Abarim (''las regiones de más allá'') designa la cadena montañosa al noroeste de Moab con vista al mar Muerto y al valle del Jordán. Su mayor importancia radica en ser el lugar desde donde Moisés contempló la Tierra Prometida antes de morir (Nm 27:12; Dt 32:49). El nombre evoca la idea de cruzar al otro lado, lo cual resulta significativo dado su papel como último punto de observación antes de la entrada de Israel en Canaán. Jeremías 22:20 lo emplea poéticamente como un lugar desde el cual se alza un clamor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5683', 'spa', 'Ebrón (topónimo, posible variante textual de Abdón)', 'Nombre de una ciudad que aparece en la lista de asentamientos de Aser en el libro de Josué, aunque la mayoría de los estudiosos considera que el texto debería leerse ''Abdón'' según los pasajes paralelos y las versiones antiguas. El lugar se menciona entre las ciudades fortificadas de la herencia de Aser. Si Ebrón es la lectura original, su ubicación es desconocida; si se trata de un error escribal por Abdón, se refiere a una ciudad levítica en la misma región.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5685', 'spa', 'marchitarse, secarse (de semillas o granos)', 'Verbo que describe el marchitamiento de los granos de cereal en el contexto del desastre agrícola de Joel. El profeta emplea esta palabra rara para retratar la pérdida total de las cosechas que acompaña la plaga de langostas: «los granos se marchitaron bajo sus terrones». Relacionado con vocablos árabes que significan contraerse o fruncirse, el término hebreo enfatiza la deshidratación y el colapso de lo que debió ser semilla viable y llena de vida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5686', 'spa', 'tejer, entrelazar (metáfora de conspiración)', 'Verbo que significa tejer o entrelazar, usado metafóricamente en Miqueas para describir las intrigas elaboradas de líderes corruptos. El profeta describe cómo «el príncipe pide, el juez acepta soborno y el poderoso dicta su mal deseo; así lo entretejen entre todos». La imagen es la de conspiradores hábiles que entrelazan sus maquinaciones como hilos en un tejido, construyendo una red unificada de corrupción con destreza artesanal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5687', 'spa', 'frondoso, de follaje espeso; dicho de árboles con ramas densas y entrelazadas', 'Este adjetivo describe árboles de follaje espeso, exuberante y con ramas entrelazadas. Levítico 23:40 prescribe tomar «ramas de árboles frondosos» para la fiesta de los Tabernáculos. Nehemías 8:15 retoma este mandato en la celebración postexílica. Ezequiel lo emplea dos veces (6:13, 20:28) para condenar la adoración idolátrica «debajo de todo árbol frondoso», donde la densa copa proporcionaba sombra y secreto para los ritos paganos. El término subraya la densidad visual y el atractivo estético o cultual de los árboles bien poblados de hojas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5688', 'spa', 'Cuerdas trenzadas, sogas o ataduras para atar; también ramas gruesas entrelazadas o follaje denso de un árbol', 'Cuerdas trenzadas, sogas o ataduras para atar; también ramas gruesas entrelazadas o follaje denso de un árbol');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5689', 'spa', 'Desear con vehemencia, codiciar sexualmente; (participio) amantes, concubinos.', 'El verbo עָגַב describe un deseo sexual intenso e ilícito, reservado casi exclusivamente para la impactante alegoría de Ezequiel sobre Jerusalén y Samaria como mujeres infieles que codician a las naciones extranjeras (Ez 23). El cognado árabe ajiba (''admirar, maravillarse'') sugiere un sentido original de atracción fascinada, pero en el uso bíblico la palabra se ha estrechado al deseo crudo y transgresor. Jeremías 4:30 emplea el participio como sustantivo — ''tus amantes'' — pasando del acto de codiciar a las personas codiciadas. El español ''se apasionó'' capta la intensidad absorbente del verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5691', 'spa', 'lascivia, deseo desmedido', 'Sustantivo femenino que denota concupiscencia o pasión desenfrenada, empleado en la alegoría de Ezequiel sobre la infidelidad de Jerusalén. El profeta describe cómo Jerusalén personificada superó incluso a su «hermana» Samaria en lascivia y prostitución. El término aparece en paralelo con «fornicaciones», subrayando la intensidad y perversidad de la idolatría de Judá, retratada como infidelidad sexual. Expresa un anhelo degradante que va más allá del simple deseo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5692', 'spa', 'Torta, pan plano; pan redondo horneado sobre brasas o piedras calientes, para comidas cotidianas y rituales.', 'Sustantivo femenino que designa una torta redonda y plana, típicamente horneada directamente sobre piedras calientes o brasas. Aparece en relatos memorables de provisión y hospitalidad: la urgencia de Abraham al preparar tortas de flor de harina para sus visitantes angélicos (Gn 18:6), las tortas sin levadura cocidas apresuradamente en el Éxodo (Éx 12:39), el maná molido y convertido en tortas (Nm 11:8), y la torta milagrosa cocida sobre brasas para Elías en el desierto (1 R 19:6). Oseas 7:8 la emplea como metáfora vívida: Efraín es ''una torta no volteada'', quemada de un lado y cruda del otro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5695', 'spa', 'Becerro, novillo joven — un bovino joven, literal o como ídolo fundido (el becerro de oro)', 'Becerro, novillo joven — un bovino joven, literal o como ídolo fundido (el becerro de oro)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5696', 'spa', 'Redondo, circular; describe la forma de objetos en el templo de Salomón, incluyendo el mar de fundición, el trono y los bastidores de las bases.', 'El adjetivo עָגֹל (agol) significa ''redondo'' o ''circular'', y aparece exclusivamente en las descripciones del mobiliario del templo de Salomón y su trono (1 Re 7:23-35; 10:19; 2 Cr 4:2). Describe el gran mar de fundición como ''redondo en todo su contorno'' (עָגֹל סָבִיב), las bases de las pilas con aberturas circulares (en contraste con מְרֻבָּעוֹת, ''cuadradas'') y el respaldo redondeado del trono real. Las seis apariciones del término se concentran en un único contexto arquitectónico-descriptivo, y las glosas multilingües — español ''redondo/a'', francés ''autour'' — confirman un significado geométrico unívoco.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5697a', 'spa', 'Novilla — vaca joven usada en sacrificios, ceremonias de pacto y como metáfora profética de naciones', 'El sustantivo עֶגְלָה (eglah) designa una vaca joven, una novilla, en contextos rituales, legales y metafóricos. La ceremonia del pacto de Abraham requiere una novilla de tres años (Gn 15:9). Deuteronomio 21:3-6 prescribe quebrar el cuello de una novilla para expiar un homicidio sin resolver. Sansón acusa a los filisteos de «arar con mi novilla» para descubrir su enigma (Jue 14:18). Los profetas emplean la novilla como metáfora nacional: Jeremías compara a Egipto con «una hermosa novilla» picada por un tábano (Jer 46:20) y a Babilonia con una novilla que trilla (Jer 50:11). Oseas retrata a Efraín como una novilla adiestrada uncida para labores más duras (Os 10:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5699', 'spa', 'Carreta o carro — vehículo con ruedas para transportar mercancías, personas u ofrendas; también la carreta de trilla que se pasa sobre el grano', 'Carreta o carro — vehículo con ruedas para transportar mercancías, personas u ofrendas; también la carreta de trilla que se pasa sobre el grano');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5700', 'spa', 'Eglon; ciudad cananea en la Sefela de Juda y tambien nombre de un rey de Moab.', 'El nombre Eglon (posiblemente derivado de עֵגֶל, ''becerro'', es decir, ''semejante a un becerro'' o ''lugar de becerros'') se refiere a dos figuras biblicas distintas: una ciudad cananea en la region de tierras bajas de Juda conquistada durante la campana sur de Josue (Jos 10:3-37; 12:12; 15:39), y el corpulento rey de Moab que oprimio a Israel durante dieciocho anos antes de ser asesinado por el juez zurdo Ehud (Jue 3:12-17). La evidencia multilingue muestra transliteracion consistente en todos los idiomas — espanol ''Eglon'', frances ''Eglon'', aleman ''Eglon'' — confirmando su condicion de nombre propio reconocido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5701', 'spa', 'afligirse, sentir angustia (por el sufrimiento ajeno)', 'Verbo que expresa profunda aflicción o angustia ante el sufrimiento de otro, presente en la defensa propia de Job. Job pregunta retóricamente: «¿No lloré yo por el que atravesaba días difíciles? ¿No se angustió mi alma por el pobre?». La palabra transmite un sufrimiento empático, la angustia interior que se experimenta al presenciar la miseria ajena. No es mera compasión intelectual, sino participación emocional en el dolor del prójimo. Cognados en arameo y posiblemente en acadio portan una intensidad emocional similar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5702', 'spa', 'recluirse (del matrimonio), permanecer sin casarse', 'Verbo en forma Nifal que significa encerrarse o confinarse, usado en Rut para la abstención voluntaria del matrimonio. Noemí pregunta a sus nueras si estarían dispuestas a «recluirse para no pertenecer a varón» mientras esperan que sus hijos recién nacidos crezcan. La imagen es de aislamiento autoimpuesto, un retirarse de la vida normal. El hebreo rabínico posterior emplea formas relacionadas para referirse a la abstención del matrimonio, confirmando este sentido de reclusión voluntaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5703', 'spa', 'Perpetuidad, para siempre; como sustantivo: duración eterna (pasada o futura); como preposición: hasta, hacia, tan lejos como.', 'Perpetuidad, para siempre; como sustantivo: duración eterna (pasada o futura); como preposición: hasta, hacia, tan lejos como.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5704', 'spa', 'Hasta, hasta que, mientras; incluso; perpetuidad; preposición y conjunción de extensión espacial, temporal y escalar', 'La partícula hebrea עַד traza una línea en el espacio, en el tiempo o en el grado y dice ''hasta aquí''. Marca el punto final de un viaje (''hasta Harán''), el límite de una duración (''hasta la mañana'') o el extremo de una escala (''ni siquiera la planta del pie''). En su variante poética עֲדֵי alcanza la eternidad en la frase עֲדֵי־עַד, ''para siempre jamás''. La pregunta retórica עַד־מָתַי o עַד־אָנָה (''¿hasta cuándo?'') resuena a lo largo de los Salmos como el clamor del afligido. El español ''hasta'' capta con precisión la direccionalidad ''hacia un límite''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5705', 'spa', 'Hasta, hacia — preposición y conjunción aramea que marca un límite temporal, espacial o cuantitativo', 'Hasta, hacia — preposición y conjunción aramea que marca un límite temporal, espacial o cuantitativo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5706', 'spa', 'Botín, presa, despojo; aquello sobre lo cual se avanza o se cae en la conquista', 'Este sustantivo designa los despojos de guerra o de caza, el premio arrebatado en la conquista. La bendición de Jacob sobre Benjamín en Génesis 49:27 lo retrata como un lobo voraz que devora la presa, profecía de la fiera reputación de la tribu. Isaías 33:23 habla de ''presa de gran botín'', un abundante cargamento de saqueo. La raíz sugiere la idea de abalanzarse sobre algo para apoderarse de ello. Sofonías 3:8 la emplea en un oráculo divino donde Dios mismo describe su ''levantarse para la presa'', una sorprendente inversión en la que Yahvé se convierte en el depredador contra las naciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5707', 'spa', 'Testigo: una persona que testifica en contextos legales, pactuales o divinos; también evidencia o testimonio (una cosa que sirve como atestación).', 'Testigo: una persona que testifica en contextos legales, pactuales o divinos; también evidencia o testimonio (una cosa que sirve como atestación).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5708', 'spa', 'menstruación, período menstrual (uso metafórico para impureza ritual)', 'Sustantivo plural que designa la menstruación o el período menstrual, empleado metafóricamente en Isaías para expresar impureza ritual. El profeta compara las mejores obras de Israel con «un vestido de menstruación»: manchado, inmundo, completamente contaminado. La imagen es deliberadamente repulsiva y subraya que incluso la justicia de la nación está corrompida por el pecado. La palabra evoca la impureza ceremonial asociada al flujo menstrual en la ley levítica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5709', 'spa', 'Pasar, cesar (Qal); quitar, deponer (Hafel) — verbo arameo usado en Daniel.', 'Un verbo arameo que aparece exclusivamente en Daniel, abarcando tanto el sentido intransitivo de ''pasar'' o ''cesar'' como el causativo de ''quitar'' o ''remover''. En sus formas Qal (Pe''al), describe cosas que dejan de existir o de continuar: el fuego ''pasó'' sobre los tres jóvenes sin hacerles daño (Dn 3:27), el reino de Nabucodonosor ''se apartó'' de él (Dn 4:31), y el dominio de Daniel ''no pasará'' jamás (Dn 7:14). El Hafel causativo se reserva para la remoción soberana del poder por parte de Dios: él ''quita reyes'' (Dn 2:21) y a Belsasar ''le quitaron'' su honra (Dn 5:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5710b', 'spa', 'Adornarse, engalanarse con joyas y atavíos; usado literalmente de mujeres y figuradamente de Israel como novia.', 'Verbo en Qal que significa adornarse o engalanarse, generalmente con joyas y vestiduras finas. En la literatura profética posee una poderosa carga metafórica: Israel es retratada como una novia que se engalana para amantes ajenos a Dios (Os 2:13, Ez 16:11-13, 23:40), mientras que los pasajes de restauración contemplan el autoadoramiento gozoso como señal del favor divino (Jer 31:4, Is 61:10). En Job 40:10 el imperativo se emplea dramáticamente cuando Dios desafía a Job a revestirse de majestad divina. El español «adornarse» y «ataviarse» captan fielmente el sentido reflexivo presente en todas las ocurrencias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5711', 'spa', 'Adá, nombre propio femenino que significa ''ornamento'' o ''mañana'', llevado por esposas de Lamec y de Esaú.', 'Nombre propio femenino que aparece en dos contextos genealógicos distintos. La primera Adá es la esposa de Lamec en la línea antediluviana (Gn 4:19-23), madre de Jabal y Jubal. La segunda es una de las esposas de Esaú, hija de Elón el heteo (Gn 36:2-16). El nombre probablemente deriva de la raíz que significa ''adornar'' (cf. H5710b), aunque BDB también señala un cognado árabe que sugiere ''mañana''. La Septuaginta lo transcribe como Adda, y todas las traducciones modernas principales — en inglés, español, francés y alemán — lo transliteran uniformemente como Adah o Ada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5712', 'spa', 'Congregación, asamblea (esp. de Israel); grupo o banda de personas; enjambre de animales', 'El término principal para la comunidad reunida de Israel en el Pentateuco. A diferencia de qahal, que subraya el acto de congregarse, edah designa la comunidad como cuerpo constituido: ''la congregación de Israel'' funciona casi como un término constitucional para el pueblo del pacto en su capacidad cúltica y cívica. La etimología (de ya''ad, ''designar, citar'') sugiere una asamblea convocada por cita más que reunida espontáneamente. En los Salmos, la misma palabra se estrecha para describir bandas hostiles, y en Jueces 14:8 se aplica incluso a un enjambre de abejas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5713a', 'spa', 'testigo, testimonio; objeto o acuerdo que sirve como evidencia legal', 'Este sustantivo femenino designa testimonio o testigo, referido específicamente a objetos inanimados que sirven como prueba. En Génesis 21:30, Abraham entrega siete corderas a Abimelec «como testimonio» de su derecho sobre un pozo. Génesis 31:52 establece un montón de piedras como «testigo» entre Jacob y Labán. Josué 24:27 declara dos veces que una gran piedra sirve de «testigo» del pacto de Israel con Dios. La fuente E prefiere esta forma femenina para objetos, mientras que J emplea el masculino עֵד.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5713b', 'spa', 'Testimonios, decretos — las estipulaciones del pacto de Dios vistas como solemnes mandatos divinos a su pueblo', 'Testimonios, decretos — las estipulaciones del pacto de Dios vistas como solemnes mandatos divinos a su pueblo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5714', 'spa', 'Idó — profeta y cronista; también otros personajes del AT que llevan este nombre', 'El nombre עִדּוֹ (Idó) pertenece a varios personajes del Antiguo Testamento. El más destacado es un profeta-cronista cuyos escritos se citan como fuentes para los reinados de Salomón, Roboam y Abías (2 Cr 9:29; 12:15; 13:22). Este Idó profético compuso «visiones» (חֲזוֹת) acerca de Jeroboam y es llamado «vidente» (חֹזֶה). El mismo personaje, o uno emparentado, aparece como abuelo del profeta Zacarías (Zac 1:1, 7; Esd 5:1; 6:14). Otros portadores del nombre incluyen un gobernador de distrito bajo Salomón (1 R 4:14), un levita descendiente de Gersón (1 Cr 6:21) y un líder sacerdotal entre los exiliados que regresaron (Neh 12:4, 16).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5715', 'spa', 'Testimonio o documento pactual, especialmente las tablas de la Ley y el Arca/Tabernáculo que las alberga; en plural, los decretos y ordenanzas de Dios', 'Testimonio o documento pactual, especialmente las tablas de la Ley y el Arca/Tabernáculo que las alberga; en plural, los decretos y ordenanzas de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5716', 'spa', 'Ornamento, joya, adorno; colectivamente, los adornos decorativos llevados sobre el cuerpo; tambien, plenitud o esplendor vital.', 'Sustantivo colectivo para ornamentos personales y galas: anillos, brazaletes y adornos de oro que representan belleza, estatus y celebracion. En 2 Samuel 1:24, se invita a las hijas de Israel a llorar por Saul, quien las vestia de escarlata con adornos de oro. Ezequiel 16:11 y 23:40 emplean el termino en metaforas extendidas donde Jerusalen es engalanada como una novia, convirtiendo el ornamento en simbolo del favor divino. La palabra tambien aparece en una lectura discutida en el Salmo 103:5, donde algunos manuscritos sugieren ''tu plenitud'' o ''tu esplendor vital'' en lugar de joyas fisicas; la Septuaginta griega lo traduce como ''tu deseo'', apuntando a un sentido abstracto de florecimiento vital.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5717', 'spa', 'Nombre propio que significa ''ornamento de El''; un simeonita, un sacerdote y el padre de un oficial de David', 'עֲדִיאֵל, que significa ''adorno/ornamento de Dios'', aparece como nombre de tres individuos en Crónicas. El elemento teofórico ''El'' combinado con una raíz que sugiere adorno o belleza crea un nombre que afirma que Dios mismo es la verdadera gloria de quien lo lleva. Uno de ellos fue un líder simeonita, otro sirvió como sacerdote, y el tercero fue padre de uno de los oficiales de David. Paralelos sabeos muestran que construcciones teofóricas similares eran comunes en las culturas del antiguo Cercano Oriente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5718', 'spa', 'Adaías, nombre propio masculino que significa ''Yahvé se ha adornado a sí mismo'', llevado por varias personas en la Biblia hebrea.', 'Un nombre propio hebreo (עֲדָיָה / עֲדָיָהוּ) que significa ''Yahvé se ha adornado a sí mismo'' o ''adornado por Yah''. Aparece a lo largo de un amplio periodo de la historia bíblica, desde el abuelo del rey Josías (2 R 22:1) hasta sacerdotes y laicos del periodo postexílico que habían tomado esposas extranjeras (Esd 10:29, 39). El nombre refleja el patrón teofórico de nomenclatura común en el antiguo Israel, combinando un verbo de belleza o adorno con el nombre divino. Las transliteraciones griegas varían considerablemente entre los manuscritos, desde Αδαια hasta Εδεινα, lo que sugiere que el nombre resultaba difícil de transcribir para los escribas de la Septuaginta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5719', 'spa', 'voluptuosa, amante del lujo (adjetivo femenino)', 'Adjetivo femenino que significa voluptuosa o amante de los placeres, usado como sustantivo para personificar a Babilonia en el oráculo de burla de Isaías. El profeta se dirige a Babilonia llamándola «¡oh voluptuosa, que habitas confiadamente!», burlándose de su complacencia autoindulgente antes de anunciar su caída repentina. El término evoca lujo, sensualidad y una falsa sensación de seguridad que será destruida sin remedio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5720', 'spa', 'Adín; nombre de un jefe de familia entre los exiliados que regresaron y de un líder postexílico', 'Adín es el nombre de al menos dos personas del período postexílico. En primer lugar, fue cabeza de una familia que regresó del exilio babilónico con Zorobabel (Esdras 2:15 // Nehemías 7:20), y miembros adicionales de su familia retornaron después con Esdras (Esdras 8:6). En segundo lugar, un Adín aparece como uno de los jefes que sellaron el pacto de Nehemías (Nehemías 10:16). El nombre podría significar «delicado» o «placer». Las versiones griegas lo transcriben como Αδ(δ)ιν o Ηδ(ε)ιν.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5721', 'spa', 'Adina (nombre propio: ''delicado, refinado'')', 'Nombre de un guerrero rubenita, uno de los valientes de David según 1 Crónicas. Adina hijo de Siza era jefe de los rubenitas y tenía treinta hombres bajo su mando. El nombre probablemente deriva de la raíz que significa «delicado» o «refinado», lo cual resulta irónico para un capitán curtido en batalla. Las versiones griegas lo transcriben como Adina o Adeina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5722', 'spa', 'Adino (nombre propio, posible corrupción textual)', 'Nombre que aparece en la lista de los valientes de David en 2 Samuel, aunque la mayoría de los eruditos consideran que el texto está corrupto y debería leerse de otro modo según el pasaje paralelo de 1 Crónicas. La frase «Adino el eznita» probablemente representa un error de copista por «blandió su lanza», como sugiere el paralelo de Crónicas. Si fuera original, el nombre derivaría de la raíz que significa «delicado» o «voluptuoso».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5723', 'spa', 'Aditaim (topónimo: forma dual, ''¿dos Aditas?'')', 'Ciudad en las tierras bajas de la Sefelá de Judá, mencionada entre los asentamientos en la distribución territorial de Josué. El nombre parece ser una forma dual, posiblemente significando «dos Aditas» o indicando un asentamiento doble. Su ubicación exacta es desconocida. Los manuscritos griegos ofrecen diversas transliteraciones, lo que refleja la incertidumbre sobre la pronunciación y el significado del nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5724', 'spa', 'Adlai (nombre propio: posiblemente ''justicia de Yah'')', 'Nombre propio que identifica al padre de Safat, uno de los oficiales administrativos del rey David. Safat hijo de Adlai estaba a cargo de los rebaños reales que pastaban en los valles (1 Cr 27:29). El nombre podría significar ''justicia de Yah'' o ''mi justicia'', incorporando un posible elemento teofórico, aunque su etimología exacta sigue siendo incierta. Las versiones griegas lo transcriben como Αδαι o Αδλι.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5725', 'spa', 'Adulam, antigua ciudad cananea en la Sefelá de Judá, célebre como cueva de refugio de David.', 'Nombre de lugar que designa la antigua ciudad real cananea de Adulam, situada en las colinas bajas (Sefelá) de Judá, a unos veintiún kilómetros al oestsuroeste de Belén. Su asociación más célebre es la cueva de Adulam, donde David reunió a su grupo de marginados mientras huía de Saúl (1 S 22:1, 2 S 23:13). La ciudad figura en la lista de conquistas de Josué (Jos 12:15), fue fortificada por Roboam (2 Cr 11:7) y se menciona nuevamente en el reasentamiento postexílico (Neh 11:30). Miqueas 1:15 la evoca en un oráculo profético. El español traduce uniformemente «Adulam».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5726', 'spa', 'Adulamita; gentilicio que designa a alguien procedente de la ciudad de Adulam', 'Este adjetivo identifica a alguien procedente de Adulam, la ciudad que más tarde sería famosa como sitio de la cueva-refugio de David. En Génesis 38, describe a Hirá, el compañero de Judá que se ve envuelto en la historia de Tamar. El término aparece tanto con artículo (''el adulamita'', refiriéndose a Hirá) como sin él (''un hombre adulamita''). Adulam era una ciudad cananea en la Sefelá, la región de tierras bajas entre la llanura costera y la serranía de Judá. La forma gentilicia sigue los patrones estándar del hebreo para crear identificadores étnicos o geográficos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5727', 'spa', 'deleitarse, regalarse (en la abundancia)', 'Verbo en forma hitpael que significa deleitarse o regalarse con placer exquisito en algo. Aparece en la confesión de Nehemías para describir cómo Israel disfrutó de la bondad de Dios durante la era de la conquista. El pueblo ''comió, se sació, engordó y se deleitó en tu gran bondad'' (Neh 9:25). El verbo implica un goce sensorial e indulgente, dirigido aquí hacia la provisión abundante de Dios, y constituye el clímax de una secuencia ascendente de satisfacción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5729', 'spa', 'Edén; territorio arameo conquistado por Asiria, probablemente idéntico a Bet-edén, ubicado en el Éufrates medio', 'Este Edén (distinto del jardín de Génesis 2-3) se refiere a un territorio arameo conquistado por el imperio asirio. La expresión «hijos de Edén» aparece en relatos de conquistas asirias, situándolos en Telasar. Ezequiel 27:23 enumera a Edén entre los socios comerciales de Tiro, junto a Harán y Cané. Los estudiosos lo identifican con el estado arameo de Bit-Adini, sobre el Éufrates medio, región bien documentada en inscripciones asirias. La vocalización hebrea lo distingue del jardín primordial. La Septuaginta lo transliteró como Edem, conservando la referencia geográfica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5730a', 'spa', 'Lujo, delicia, deleite; abundancia placentera, ya sea refinamiento material o gozo espiritual', 'Este sustantivo capta la idea de delicias exquisitas y placeres refinados. En 2 Samuel 1:24 describe las vestiduras lujosas que Saúl proporcionaba a las hijas de Israel. Jeremías 51:34 lo emplea metafóricamente: Nabucodonosor ha llenado su vientre con las «delicias» de Judá, saqueando sus tesoros. En el Salmo 36:8, con gran belleza, se habla del «río de tus delicias», paralelo a la «abundancia de tu casa», describiendo los gozos profundos de adorar a Yahveh. La raíz sugiere un placer refinado, nacido de la abundancia y la hermosura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5731b', 'spa', 'Eden; la region-jardin primordial de Dios donde moraron Adan y Eva, arquetipo de bendicion divina y fertilidad.', 'Nombre propio del territorio donde Dios planto un jardin para la primera morada de la humanidad (Gn 2:8). Probablemente asociado con el hebreo עֵדֶן que significa ''delicia'' o ''lujo'', el nombre evoca un lugar de provision abundante e inmerecida: un rio fluye de Eden para regar el jardin y luego se divide en cuatro brazos (Gn 2:10). Tras la expulsion, querubines y una espada flamigera custodian el camino de regreso al arbol de la vida (Gn 3:24). Profetas posteriores invocan Eden como la simil suprema de fertilidad restaurada: ''el SENOR hara su desierto como Eden'' (Is 51:3; cf. Ez 36:35; Jl 2:3). Ezequiel 28 y 31 lo desarrollan como ''el jardin de Dios'', rico en piedras preciosas y arboles imponentes. La Septuaginta lo traduce como Eden y he tryphe (''la delicia'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5732', 'spa', 'Tiempo, período, estación; sustantivo arameo en Daniel para duración general o unidades proféticas de años.', 'Este sustantivo arameo iddan aparece exclusivamente en el libro de Daniel, donde funciona como término principal para ''tiempo'' tanto en sentido general como profético. En su uso ordinario designa un período o estación (Dan 2:8–9, 21; 3:5, 15; 7:12). En su aplicación profética opera como unidad técnica equivalente a un año, como en ''siete tiempos'' (Dan 4:13, 20, 22, 29), refiriéndose a los siete años de locura de Nabucodonosor, y en la fórmula críptica ''un tiempo, tiempos y medio tiempo'' (Dan 7:25), que representa tres años y medio. El término probablemente deriva del acadio adannu (''tiempo señalado''), incorporado al arameo como préstamo lingüístico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5735', 'spa', 'Adadá (topónimo, posible corrupción textual por Aroer)', 'Nombre de lugar en la lista de ciudades del sur de Judá, aunque algunos eruditos proponen leer ''Aroer'' en su lugar, basándose en otras referencias geográficas. Si la lectura es original, Adadá resulta desconocida por otras fuentes. El sitio aparece en la asignación territorial de Josué a Judá, entre los asentamientos más meridionales hacia la frontera edomita (Jos 15:22). La similitud del nombre con otras variantes textuales ha generado un debate continuo sobre la lectura correcta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5736', 'spa', 'Sobrar, estar de más; lo sobrante o excedente (aplicado a cortinas, alimentos, dinero y personas)', 'Verbo empleado casi exclusivamente como participio con función sustantiva: ''el sobrante'', ''el excedente'', ''lo que queda de más''. Aparece destacadamente en las instrucciones del tabernáculo, donde el material sobrante de las cortinas debe contabilizarse (Éx 26:12-13), y en la narración del maná, donde lo recogido no debe tener sobrante (Éx 16:18, 23). La única forma Hifil, en Éxodo 16:18, pasa de la descripción a la acción: ''el que recogió mucho no tuvo exceso'', señalando el milagro de una provisión perfectamente proporcionada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5737a', 'spa', 'ayudar, asistir (préstamo arameo, posible variante textual)', 'Préstamo del arameo que significa ayudar, presente en un pasaje textualmente incierto de 1 Crónicas. La expresión ''para ayudar'' en 12:34 probablemente representa una variante escribal de la raíz hebrea más común que significa ''ordenar'' o ''disponer en formación'', usada en otros lugares del capítulo para describir la disposición de líneas de batalla. Fuentes siríacas y rabínicas emplean esta raíz aramea como equivalente del hebreo ''ayudar''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5737c', 'spa', 'Faltar, estar ausente, no estar presente (Nifal/Piel); siempre usado con negación para enfatizar completitud.', 'Verbo en las formas Nifal y Piel que significa ''faltar, estar ausente o no encontrarse'', notablemente casi siempre acompañado de la partícula negativa (לֹא). Esto genera una afirmación enfática de totalidad: en 1 Samuel 30:19 nada «faltaba» de lo que los amalecitas habían tomado; en 2 Samuel 17:22 no faltó ni una sola persona que no hubiera cruzado el Jordán. Isaías 40:26 lo aplica a escala cósmica: Dios llama a las estrellas por nombre y «ninguna falta». Sofonías 3:5 lo usa respecto a Dios mismo: cada mañana ejecuta justicia y «no falla».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5738', 'spa', 'Eder (nombre propio: ''rebaño, manada'')', 'Nombre propio benjamita que significa ''rebaño'' o ''manada'', presente en los registros genealógicos de 1 Crónicas. Eder fue uno de los hijos enumerados en la familia de Benjamín (1 Cr 8:15). El nombre emplea un sustantivo común referido a un grupo de animales como designación personal, reflejando posiblemente una herencia pastoral. Las versiones griegas ofrecen diversas transcripciones del nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5739', 'spa', 'Rebaño, hato — grupo de ganado (ovejas, cabras o vacas) apacentado junto, frecuente en la imaginería pastoral', 'Rebaño, hato — grupo de ganado (ovejas, cabras o vacas) apacentado junto, frecuente en la imaginería pastoral');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5740b', 'spa', 'Eder (topónimo en el extremo sur de Judá)', 'Ciudad ubicada en el extremo sur del territorio de Judá, enumerada entre los asentamientos cercanos a la frontera con Edom. Eder aparece en el catálogo de ciudades de Judá en Josué, aunque su ubicación exacta se desconoce. El nombre significa ''rebaño'' o ''manada'', lo que posiblemente indica un asentamiento pastoral o un lugar de abrevadero para el ganado. Las versiones griegas muestran variaciones considerables en la transliteración del nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5742', 'spa', 'lentejas; legumbre usada como alimento, especialmente en guisos y pan', 'Las lentejas son una legumbre común en el antiguo Cercano Oriente, cultivada como cosecha de campo y alimento básico. Génesis 25:34 relata cómo Esaú vendió su primogenitura por un «guiso de lentejas». 2 Samuel 17:28 enumera las lentejas entre las provisiones llevadas a David, mientras que 2 Samuel 23:11 narra una batalla librada en un campo de lentejas. Ezequiel 4:9 las incluye en la receta simbólica de pan del profeta. Las lentejas proporcionaban proteínas y eran un componente esencial de la dieta campesina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5743', 'spa', 'nublar, cubrir con nube (metáfora del juicio divino)', 'Verbo en forma hifil que significa cubrir con una nube o envolver en oscuridad, empleado en Lamentaciones para describir el juicio de Dios sobre Jerusalén. El profeta exclama: ''¡Cómo ha nublado el Señor a la hija de Sión en su ira!'' La imagen presenta la ira divina descendiendo como un nubarrón tormentoso que oscurece y oculta lo que antes era glorioso. El verbo intensifica la sensación de alienación y juicio por parte de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5744', 'spa', 'Obed (''adorador''), nombre propio; principalmente el hijo de Booz y Rut, abuelo del rey David', 'Nombre propio que significa «adorador» o «siervo», derivado de la raíz ʿabad («servir»). El portador más destacado es el hijo de Booz y Rut, cuyo nacimiento celebraron las mujeres de Belén como restaurador del linaje de Noemí (Rt 4:17). Las genealogías de Rut 4:21-22 y 1 Crónicas 2:12 sitúan a Obed como el eslabón entre Booz y Jesé, convirtiéndolo en abuelo de David y figura clave en el linaje mesiánico. Otros portadores incluyen un judahita en 1 Crónicas 2:37-38, un valiente guerrero de David (1 Cr 11:47) y un portero del templo (1 Cr 26:7).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5745', 'spa', 'Obal (nombre personal/tribal: posible grupo arábigo)', 'Descendiente de Joctán incluido en la Tabla de las Naciones, que representa un grupo étnico arábigo. Obal aparece en Génesis 10 entre los hijos de Joctán, ancestro de diversas tribus del sur de Arabia. El pasaje paralelo en 1 Crónicas lo llama Ebal, lo que refleja el intercambio de las vocales ''o'' y ''e'' en tradiciones textuales variantes. La ubicación o el pueblo específico que representa sigue siendo incierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5746', 'spa', 'hornear (una torta de pan), formar en hogaza redonda', 'Verbo denominativo que significa hornear una torta o dar forma redonda al pan, utilizado en la acción simbólica de Ezequiel. Dios ordena al profeta hornear tortas de cebada sobre un fuego alimentado con estiércol humano, simbolizando el alimento contaminado que Israel comerá en el exilio. El verbo deriva del sustantivo que designa una torta redonda de pan, enfatizando el proceso de darle forma y cocerla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5747', 'spa', 'Og — el rey gigante de Basán, derrotado por Israel junto con Sijón como victorias paradigmáticas de conquista', 'Og — el rey gigante de Basán, derrotado por Israel junto con Sijón como victorias paradigmáticas de conquista');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5748', 'spa', 'flauta, caramillo; instrumento de viento, posiblemente flauta de caña, siringa o gaita', 'Este instrumento musical aparece en contextos tanto antiguos como poéticos. Génesis 4:21 atribuye a Jubal ser el padre de todos los que tocan el arpa y la flauta (עוּגָב), vinculándolo con los logros culturales más tempranos de la humanidad. Job lo emplea en contextos de alegría (21:12) y de lamento (30:31), mientras que el Salmo 150:4 lo incluye en la gran alabanza orquestal a Dios. Su identificación exacta es debatida: el Targum sugiere una flauta de caña, la Vulgata una siringa, y algunos estudiosos modernos proponen una gaita o instrumento de cuerda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5749a', 'spa', 'rodear, cercar, testificar; mantenerse en pie o dar testimonio solemne', 'Esta raíz verbal abarca sentidos relacionados de rodear, repetir, testificar y mantenerse erguido, derivados de la idea de retorno y restauración. Su campo semántico es amplio: el Salmo 119:61 habla de las cuerdas de los impíos que rodearon al salmista, mientras que otras referencias implican mantenerse firme (Salmo 20:8), sostener (Salmo 146:9) o levantar (Salmo 147:6). La raíz posiblemente se conecta con el árabe עוד (volver, repetir) y está emparentada con el sustantivo עֵדוּת (testimonio), sugiriendo un movimiento que retorna o reafirma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5749b', 'spa', 'Testificar, advertir o exhortar solemnemente; también convocar o llamar como testigo', 'Testificar, advertir o exhortar solemnemente; también convocar o llamar como testigo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5750', 'spa', 'Todavía, aún, otra vez, más, además; continuación o repetición de acción o estado; también ''otro'' y temporal ''mientras aún''', 'Adverbio versátil construido sobre la idea de continuidad, ''od funciona como el recurso hebreo por excelencia para expresar persistencia (''todavía, aún''), recurrencia (''otra vez, de nuevo'') y adición (''además, más''). Con sufijos pronominales forma cláusulas temporales compactas —''mientras él aún hablaba''— que en español requieren una subordinada completa. Su alcance abarca desde la duración temporal hasta la afirmación existencial ''no hay otro'' (Dt 4:35), revelando cómo el hebreo comprime tiempo e identidad en una sola partícula de continuación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5751', 'spa', 'aún, todavía (adverbio temporal arameo)', 'Adverbio arameo que significa ''aún'' o ''todavía'', indicando una acción o estado en curso. En Daniel, describe cómo las palabras jactanciosas de Nabucodonosor estaban aún en su boca cuando cayó el juicio divino. El adverbio subraya la inmediatez de la respuesta de Dios: incluso antes de que el rey terminara de hablar, la sentencia fue ejecutada. La palabra es frecuente en el arameo bíblico y en la literatura rabínica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5752', 'spa', 'Nombre propio que significa «restaurador»; profeta en Crónicas y padre del profeta Azarías', 'Oded, que significa «restaurador» o «el que restaura», es el nombre de dos figuras proféticas en Crónicas. Uno fue padre de Azarías, el profeta que alentó las reformas del rey Asá; el texto de 2 Crónicas 15:8 a veces se enmienda para leer «Azarías hijo de Oded el profeta». El segundo Oded fue un profeta del reino del norte que confrontó al ejército israelita victorioso, exigiendo la liberación de los cautivos de Judá. El nombre encierra una afirmación teológica: Dios restaura a su pueblo, algo muy apropiado para profetas que llamaban a la renovación del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5753a', 'spa', 'Torcer, pervertir o desviar; en Nifal, estar encorvado, distorsionado o moralmente torcido.', 'Verbo construido sobre la imagen de torcer o curvar lo que debería ser recto. En las formas Hifil y Piel describe la distorsión activa, ya sea moral o física: Elihú confiesa «lo recto yo lo torcí» (Job 33:27), Jeremías acusa a Israel de haber «torcido su camino» (Jer 3:21) e Isaías advierte que Dios «trastornará la faz» de la tierra (Is 24:1). En el Nifal expresa el estado resultante de estar doblado o deformado: el salmista clama «estoy encorvado» (Sal 38:6) y Proverbios advierte contra el de «corazón torcido» (Pr 12:8). El cognado árabe ʿawā (''doblar, torcer'') confirma la imagen física central que subyace a los sentidos tanto morales como físicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5753b', 'spa', 'Cometer iniquidad, actuar perversamente, obrar mal; denominativo de ''avon (iniquidad), en las formas Qal, Hifil y Nifal', 'Derivado del sustantivo ''avon (iniquidad/culpa), este verbo aparece en contextos confesionales y judiciales donde se reconoce o describe una falla moral. La gran oración de Salomón lo incluye en una tríada con «pecamos» y «actuamos perversamente» (1 R 8:47), fórmula que se repite en Daniel 9:5 y Salmo 106:6. David emplea el Hifil tras el desastre del censo: «he obrado muy perversamente» (2 S 24:17), mientras que el único participio Nifal en 1 Samuel 20:30 describe un estado de perversión. El español lo traduce consistentemente con «iniquidad» y «perversamente», conservando el peso moral del original.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5754', 'spa', 'Distorsión, ruina; destrucción retorcida, frecuentemente repetida tres veces para dar énfasis', 'Este sustantivo denota distorsión y ruina: algo torcido hasta perder su forma propia. Aparece célebremente en Ezequiel 21:27 en una impactante triple repetición: «¡Ruina, ruina, ruina haré de ella!». La triple repetición martilleante crea un efecto casi encantatorio, subrayando la totalidad de la destrucción venidera. El verbo raíz significa torcer o pervertir, y el sustantivo captura el resultado: algo deformado más allá de todo reconocimiento, completamente arruinado. Ezequiel lo usa para describir la inminente caída de Jerusalén y su monarquía, una destrucción tan absoluta que requiere tres declaraciones para transmitir su carácter definitivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5755', 'spa', 'Iva (también Ava); ciudad conquistada por los asirios, ubicada en el norte de Siria', 'Iva fue una ciudad conquistada por el imperio asirio, mencionada en las jactancias asirias registradas en 2 Reyes e Isaías. El Rabsaces se burla de Ezequías enumerando ciudades cuyos dioses no pudieron salvarlas, incluyendo Iva (2 Reyes 18:34, 19:13 // Isaías 37:13). En 2 Reyes 17:24 se menciona que gente de Ava fue reasentada en Samaria. El sitio probablemente se encontraba en el norte de Siria, posiblemente la moderna ʿImm entre Antioquía y Alepo, aunque las identificaciones varían.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5756', 'spa', 'refugiarse, buscar protección, huir a lugar seguro; poner a salvo', 'Este verbo describe la acción de buscar refugio o poner a otros a salvo en tiempos de peligro. El infinitivo Qal aparece en Isaías 30:2, condenando a quienes «se refugian bajo la protección del faraón». El imperativo Hifil ordena huir a lugar seguro: «¡Huid!» (Jeremías 4:6, 6:1), «¡Refugiaos!» (Isaías 10:31), o «¡Poned a salvo!» (Éxodo 9:19, advirtiendo que se resguarde el ganado del granizo). La raíz es cognada del árabe عَاذَ (refugiarse, buscar protección) y enfatiza el movimiento protector para alejarse del peligro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5758', 'spa', 'iniquidades (plural arameo con sufijo pronominal, referente a perversidad moral)', 'Sustantivo arameo en plural que significa iniquidades o pecados, y aparece con sufijo pronominal en el libro de Daniel. Se encuentra en la interpretación de Daniel al rey Nabucodonosor, cuando le aconseja: «Rompe con tus iniquidades practicando la justicia». La forma aramea corresponde a la raíz hebrea que denota perversidad o iniquidad, aludiendo a la torcedura moral y la rebelión contra Dios. El plural enfatiza la acumulación de culpa que exige arrepentimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5760', 'spa', 'persona injusta, perverso (usado como sustantivo)', 'Sustantivo masculino que designa a una persona injusta o perversa, y aparece en el lamento de Job. Job se queja de que Dios lo ha entregado en manos del «perverso» o del «injusto». El término enfatiza la perversidad moral y la injusticia más que la pecaminosidad general. Puede referirse a enemigos concretos o emplear el singular de forma colectiva para designar a los malvados como clase. El contexto subraya la sensación de abandono e indefensión que experimenta Job.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5762', 'spa', 'Avit; ciudad de Edom, capital del rey Hadad', 'Avit fue una ciudad de Edom que sirvió como sede real de Hadad, uno de los primeros reyes edomitas enumerados en Génesis 36. La ciudad aparece en el registro genealógico de gobernantes edomitas que reinaron «antes de que hubiese rey sobre los hijos de Israel», como parte del material de las tablas de las naciones. Su ubicación es hoy desconocida, perdida entre los asentamientos cambiantes del antiguo Edom. El pasaje paralelo en Crónicas conserva una variante ortográfica (Ketiv: Ayot), mostrando variación textual en la transmisión de este oscuro topónimo. Las diversas transliteraciones de la Septuaginta reflejan la incertidumbre antigua sobre la vocalización exacta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5763', 'spa', 'Amamantar, dar de mamar; dicho de ovejas, vacas, o figuradamente de Dios guiando con ternura a su pueblo', 'Este verbo describe el acto de amamantar o criar a las crías, aplicado al ganado: vacas (1 S 6:7, 10) y ovejas (Sal 78:71), y extendido figuradamente al tierno cuidado de Dios por su pueblo. En Isaías 40:11 las ovejas que crían se convierten en metáfora de los exiliados que regresan, a quienes el Señor guía con delicadeza. Génesis 33:13 lo emplea para expresar la preocupación de Jacob por sus rebaños que están criando. El cognado árabe غَلَى confirma el significado fundamental de dar de mamar estando preñada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5764', 'spa', 'Niño lactante, criatura de pecho; infante que aún depende de la leche materna', 'Este sustantivo designa a un niño lactante, una criatura que todavía depende de la leche materna. Isaías 49:15 lo emplea en una tierna pregunta retórica: «¿Acaso puede una mujer olvidarse de su niño de pecho?», donde el término paralelo «hijo de sus entrañas» refuerza la intimidad del vínculo. En Isaías 65:20, aparece en la expresión «lactante de pocos días», como parte de la visión donde incluso los recién nacidos gozarán de larga vida en la creación restaurada. Job 24:9 denuncia con dureza a los impíos que arrebatan al lactante del pecho, imagen de explotación violenta y colapso social.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5766a', 'spa', 'Injusticia, iniquidad; desviación moral de lo justo y recto, frecuentemente opuesta a tzedaqah (justicia).', 'Injusticia, iniquidad; desviación moral de lo justo y recto, frecuentemente opuesta a tzedaqah (justicia).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5766b', 'spa', 'Injusticia, iniquidad o perversidad moral; maldad que viola lo recto, ya sea en las relaciones sociales o en el caracter', 'Injusticia, iniquidad o perversidad moral; maldad que viola lo recto, ya sea en las relaciones sociales o en el caracter');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5767', 'spa', 'Persona injusta, inicuo; opresor que pervierte la justicia', 'Adjetivo sustantivado que designa a una persona caracterizada por la injusticia y la perversión moral, frecuentemente en paralelo con רָשָׁע (''malvado''). En Job describe el destino que aguarda al injusto (18:21; 27:7; 31:3) y al opresor cuya mandíbula Job quebró (29:17). Sofonías 3:5 contrasta a Dios, que no comete injusticia, con el gobernante inicuo que no conoce la vergüenza. La palabra conlleva una fuerte carga ética de violación deliberada del orden justo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5768', 'spa', 'Infante o nio muy pequeo, que aparece frecuentemente en contextos de vulnerabilidad, guerra y juicio colectivo. Se refiere a los miembros ms jvenes y ', 'Infante o nio muy pequeo, que aparece frecuentemente en contextos de vulnerabilidad, guerra y juicio colectivo. Se refiere a los miembros ms jvenes y vulnerables de una comunidad: lactantes y nios pequeos. Esta palabra aparece con frecuencia en algunos de los pasajes ms sobrecogedores de las Escrituras: la masacre en Nob (1 Sam 22:19), la profeca de Eliseo sobre la brutalidad de Hazael (2 Re 8:12) y el desgarrador clamor del Salmo 137:9. Emparejada a menudo con ''lactante'' (yoneq), intensifica la totalidad de la destruccin o el sufrimiento. Sin embargo, tambin aparece en contextos de cuidado divino: ''de la boca de los nios has establecido la fortaleza'' (Sal 8:2). Lamentaciones la usa repetidamente para retratar la agona del asedio de Jerusaln.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5769', 'spa', 'Larga duración; eternidad, para siempre; antigüedad, tiempos remotos; perpetuo (atributivo); era(s) o siglo(s)', 'Olam es uno de los sustantivos de mayor peso teológico en la Biblia hebrea, pero su significado no es simplemente ''eternidad'' en sentido filosófico. En su núcleo, olam apunta a una duración que se extiende más allá de la vista ordinaria: hacia un futuro ilimitado (''para siempre''), hacia las brumas de la antigüedad (''desde antiguo''), o cualitativamente como atributo permanente de pactos, estatutos y promesas divinas. El estribillo le''olam jasdo (''para siempre es su misericordia'') resuena veintiséis veces en el Salmo 136, y sin embargo la misma palabra describe las ''sendas antiguas'' de Jeremías 6:16 y los ''hombres de antaño'' de Génesis 6:4. Su genio reside en negarse a reducir el tiempo a una sola dirección.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5769b', 'spa', 'Olam (nombre propio, posiblemente ''eternidad'' o ''juventud'')', 'Nombre propio que aparece entre quienes se casaron con mujeres extranjeras durante el período postexílico. Olam figura en Esdras 10 entre los israelitas que habían contraído matrimonios mixtos y fueron llamados a separarse. El nombre es idéntico a la palabra común que significa «eternidad» o «larga duración», aunque aquí funciona como designación personal. El contexto es la reforma religiosa emprendida bajo la dirección de Esdras para preservar la pureza del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5770', 'spa', 'mirar con recelo, observar con envidia o celos', 'Verbo denominativo derivado de «ojo» que significa mirar a alguien con envidia o sospecha. Aparece en 1 Samuel describiendo la actitud de Saúl hacia David después de que las mujeres cantaran alabando las victorias de David. «Saúl miraba con recelo a David desde aquel día en adelante»: una vigilancia continua y celosa. El verbo capta la idea de mantener una mirada suspicaz y envidiosa sobre alguien percibido como rival, expresando hostilidad latente más que simple observación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5771', 'spa', 'Iniquidad, pecado, maldad; culpa, responsabilidad por el pecado; castigo o consecuencia del pecado', 'El sustantivo hebreo avon abarca todo el ciclo vital del pecado: el acto torcido en sí, la culpa que se adhiere al infractor y el castigo que le sigue. Cuando Caín clama ''mi avon es mayor de lo que puedo soportar'' (Gn 4:13), la palabra fusiona deliberadamente los tres significados: su crimen, su culpa y su sentencia, comprimidos en un solo término. El peso teológico es inmenso: avon es lo que el siervo carga vicariamente en Isaías 53:6 y lo que Dios ''pasa por alto'' en la gran confesión de Miqueas 7:18.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5772', 'spa', 'derechos conyugales, deber marital (especialmente el derecho de la esposa a la intimidad dentro del matrimonio)', 'Este término se refiere a los derechos maritales debidos dentro del pacto matrimonial, particularmente la intimidad física que forma parte del vínculo conyugal. La raíz hebrea probablemente se relaciona con ideas de correspondencia y reciprocidad entre esposo y esposa. En Éxodo 21 aparece en una lista de tres derechos básicos que la esposa conserva incluso si su marido toma otra mujer: alimento, vestido y relaciones conyugales. El término subraya que la intimidad física no es opcional sino una obligación del pacto, protegiendo la dignidad y los derechos de la esposa dentro de la relación matrimonial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5773', 'spa', 'distorsión, perversión, juicio torcido (sustantivo abstracto que describe un razonamiento desviado o retorcido)', 'Este raro sustantivo abstracto en plural describe un estado de distorsión mental o moral, un retorcimiento de la percepción que conduce a un juicio desviado. La raíz sugiere algo doblado o desviado de la rectitud. En Isaías 19, caracteriza el ''espíritu de confusión'' que YHWH derramará sobre Egipto, haciendo que sus consejeros den consejos insensatos y sus príncipes extravíen a la nación. El término capta no solo el error, sino una distorsión sistemática, como si la facultad misma del juicio hubiera sido torcida, haciendo imposible el pensamiento recto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5774a', 'spa', 'Volar, remontarse; moverse velozmente por el aire; tambien desfallecer o agotarse; blandir', 'Volar, remontarse; moverse velozmente por el aire; tambien desfallecer o agotarse; blandir');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5774b', 'spa', 'oscuridad, tiniebla (probable variante textual en Job 11:17, contrastada con la luz de la mañana)', 'Este término aparece en un pasaje textualmente difícil de Job y probablemente se refiere a oscuridad o tiniebla profunda. BDB sugiere leerlo como sustantivo con el significado de ''oscuridad'' en Job 11:17, donde Zofar promete a Job que su vida será más brillante que el mediodía, y que incluso lo que parece tiniebla se convertirá en mañana. El contexto apoya firmemente el significado de ''oscuridad'' como opuesto de la luz matutina. El pasaje ofrece esperanza de que las circunstancias sombrías de Job darán paso al resplandor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5775', 'spa', 'Criaturas voladoras colectivamente: aves, pájaros (del cielo, de rapiña, para sacrificio); raramente insectos alados en las listas levíticas de animal', 'Criaturas voladoras colectivamente: aves, pájaros (del cielo, de rapiña, para sacrificio); raramente insectos alados en las listas levíticas de animales puros e impuros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5777', 'spa', 'Plomo, el metal pesado de color gris azulado, mencionado en contextos de metalurgia, inscripción permanente y mercancías comerciales.', 'Designa el metal plomo (עֹפֶרֶת), probablemente un préstamo de origen incierto. Aparece en inventarios de metales junto al estaño, el hierro y el bronce (Nm 31:22; Ez 22:18, 20) y como mercancía de Tarsis (Ez 27:12). Su uso más memorable está en Job 19:24, donde Job desea que sus palabras fueran grabadas con buril de hierro y rellenadas con plomo para que perdurasen. El Cántico del Mar lo emplea en un símil sorprendente: los egipcios ''se hundieron como plomo en las aguas impetuosas'' (Éx 15:10). La visión de Zacarías utiliza un disco de plomo como tapa del efa (Zac 5:7-8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5780', 'spa', 'Uz, nombre propio de personas en genealogías arameas/edomitas y nombre de la región oriental donde habitaba Job.', 'Sustantivo propio que funciona tanto como nombre personal como designación geográfica. Como nombre de persona, Uz aparece en tres líneas genealógicas: hijo de Aram y nieto de Sem (Gn 10:23, 1 Cr 1:17), primogénito de Nacor (Gn 22:21) y descendiente edomita de Seír (Gn 36:28, 1 Cr 1:42). Como topónimo, designa el territorio oriental donde habitó Job (Job 1:1) y una región mencionada en juicios proféticos (Jer 25:20, Lm 4:21). La convergencia de tradiciones arameas, nahoritas y edomitas sugiere una amplia zona fronteriza al este de Israel. La Septuaginta lo traduce como Aus/Os.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5782', 'spa', 'Despertar, levantar, avivar; en Qal, despertar del sueño; en Hifil, causar despertar o incitar a la acción; en Piel, avivar intensivamente.', 'Despertar, levantar, avivar; en Qal, despertar del sueño; en Hifil, causar despertar o incitar a la acción; en Piel, avivar intensivamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5783', 'spa', 'ser puesto al descubierto, desenvainado, preparado (de un arco desenfundado y listo para el combate)', 'Este verbo en forma Nifal significa ser expuesto, puesto al descubierto o completamente preparado. Aparece en la visión profética de Habacuc describiendo el arco de Dios completamente listo para la batalla, ''desnudado por completo'', es decir, desenvainado y preparado para herir. La raíz se conecta con ideas de desnudez y exposición. Aunque algunos eruditos proponen enmiendas textuales, la imagen de un arma plenamente expuesta y lista capta la intensidad del juicio divino. Las glosas multilingües reflejan tanto la idea de ''poner al descubierto'' como la de ''despertar'' para la acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5784', 'spa', 'tamo, cascarilla seca (residuo liviano que el viento dispersa al trillar y aventar el grano)', 'Este sustantivo arameo se refiere al tamo, las cascarillas livianas y secas que se separan del grano durante la trilla y el aventamiento. En la visión de Daniel sobre el sueño de Nabucodonosor, la gran estatua que representa reinos sucesivos es golpeada por una piedra y se deshace en pedazos que se vuelven ''como tamo de las eras de verano'', llevados por el viento sin dejar rastro. La imagen enfatiza la desaparición total y la insignificancia de estos poderosos imperios ante el reino eterno de Dios. Palabras afines en arameo y árabe se refieren igualmente a partículas menudas, subrayando la idea de fragmentos sin valor fácilmente esparcidos por el viento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5785', 'spa', 'Piel, cuero, pellejo; la cobertura exterior del cuerpo humano, el pellejo de un animal o el cuero procesado', 'Desde las primeras vestiduras del Edén —''túnicas de pieles'' confeccionadas por Dios para Adán y Eva (Gn 3:21)— hasta las minuciosas regulaciones de pureza de Levítico, or funciona como un término concretamente físico que abarca la vulnerabilidad humana, el sacrificio animal y la cultura material. La palabra domina Levítico 13, donde treinta y tres ocurrencias detallan la inspección de afecciones cutáneas. Los gritos angustiados de Job (''mi piel se pega a mis huesos'', Job 19:20) y la pregunta retórica de Jeremías sobre la piel del etíope (Jr 13:23) la convierten en una palabra de sufrimiento encarnado. Cuando se procesa como cuero, cubre el tabernáculo (Éx 26:14) y debe purificarse al contaminarse (Lv 11:32).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H5786', 'spa', 'Cegar, sacar los ojos (Piel); usado literalmente de cegar cautivos y figuradamente del soborno que corrompe el juicio', 'En la conjugación Piel, este verbo significa cegar o sacar los ojos a alguien. Su uso literal describe el brutal castigo infligido al rey Sedequías por Nabucodonosor (2 R 25:7; Jer 39:7; 52:11). En sentido figurado, tanto Éxodo 23:8 como Deuteronomio 16:19 advierten que el soborno ciega los ojos de los sabios y de quienes ven con claridad. Los cognados arameo y árabe confirman el significado raíz de dañar la vista. La imagen compartida entre los usos literal y figurado es la destrucción de la capacidad de ver.');